-- Descripción de cada tema (se muestra arriba en tema.php)
UPDATE topics SET descripcion = 'Las células del sistema nervioso son de dos grandes familias: las neuronas, especializadas en generar y transmitir señales eléctricas, y la glía, que las sostiene, aísla y regula su entorno químico. Entender su morfología es el punto de partida para todo lo demás.' WHERE slug = 'celulas-sn';
UPDATE topics SET descripcion = 'El potencial de acción es la señal eléctrica con la que la neurona comunica información a distancia. Se produce por la apertura y cierre ordenados de canales de sodio y potasio, y viaja por el axón sin perder amplitud.' WHERE slug = 'potencial-accion';
UPDATE topics SET descripcion = 'La sinapsis es el punto de contacto donde una neurona transfiere información a otra célula. Aquí la señal eléctrica se convierte en química (neurotransmisores) y vuelve a ser eléctrica en la célula postsináptica.' WHERE slug = 'sinapsis';
UPDATE topics SET descripcion = 'El sistema nervioso sensitivo recoge información del cuerpo y del ambiente mediante receptores especializados, la codifica en potenciales de acción y la conduce hasta la corteza, donde se transforma en percepción.' WHERE slug = 'sn-sensitivo';
UPDATE topics SET descripcion = 'El sistema nervioso autónomo regula, sin control voluntario, las funciones viscerales: frecuencia cardíaca, respiración, digestión y secreciones. Sus dos divisiones, simpática y parasimpática, actúan de forma complementaria.' WHERE slug = 'sn-autonomo';
UPDATE topics SET descripcion = 'La neurona es la unidad funcional del sistema nervioso: recibe señales por sus dendritas, las integra en el soma y las propaga por el axón hacia sus botones terminales.' WHERE slug = 'neurona';
UPDATE topics SET descripcion = 'Las células gliales superan en número a las neuronas. Astrocitos, oligodendrocitos, células de Schwann, microglía y ependimarias sostienen, nutren, mielinizan y defienden el tejido nervioso.' WHERE slug = 'glia';
UPDATE topics SET descripcion = 'La forma de una neurona anticipa su función: el número de prolongaciones, la longitud del axón y la presencia de mielina determinan qué tan lejos y qué tan rápido puede enviar su señal.' WHERE slug = 'morfologia-neurona';
UPDATE topics SET descripcion = 'Los canales iónicos son proteínas de membrana que dejan pasar iones específicos. Su apertura dependiente de voltaje o de ligando es lo que hace posible el potencial de acción y la transmisión sináptica.' WHERE slug = 'canales-ionicos';
UPDATE topics SET descripcion = 'Los neurotransmisores son las moléculas que cruzan la hendidura sináptica. Según el receptor al que se unan, pueden excitar o inhibir a la célula postsináptica.' WHERE slug = 'neurotransmisores';

-- Actividad 1: LÁMINA virtual Golgi (piramidal y Purkinje)
INSERT OR IGNORE INTO actividades (id, topic_id, slug, titulo, descripcion, tipo, activo) VALUES
  (1, 6, 'lamina-neurona-piramidal', 'Lámina: neuronas reales',
       'Corte sagital de cerebro de rata en dos tinciones. Nivel I: oriéntate en el corte. Nivel II: con Golgi, encuentra una neurona piramidal y una célula de Purkinje, captúralas, recórtalas y etiquétalas. Nivel III: compara el cerebelo con Golgi y con cresil violeta.',
       'lamina', 1);
-- Recurso "tareas" con niveles: el nivel 1 usa el motor de identificación (labeling_parts de esta actividad);
-- los niveles de capturas los maneja js/lamina.js
INSERT OR IGNORE INTO actividad_recursos (actividad_id, tipo, url, caption, orden) VALUES
  (1, 'tareas', '{"laminas": {"golgi": {"nombre": "Golgi (plata)", "url": "https://histologyguide.com/slideview/MHS-284-brain/06-slide-1.html?page=2", "caption": "Corte sagital de cerebro de rata — método de Golgi (histologyguide.com)"}, "cresil": {"nombre": "Cresil violeta (Nissl)", "url": "https://histologyguide.com/slideview/MHS-283-brain/06-slide-1.html", "caption": "Corte sagital de cerebro de rata — cresil violeta (histologyguide.com)"}}, "niveles": [{"n": 1, "tipo": "identificar", "titulo": "Orientación en el corte", "img": "img/corte-sagital-rata.jpg", "aviso_rata": true}, {"n": 2, "tipo": "capturas", "titulo": "Piramidal y Purkinje con Golgi", "laminas": ["golgi"], "instrucciones": "Para cada neurona sigue los 4 pasos del panel: buscar y capturar, recortar, etiquetar y responder. <strong>Verde</strong>: correcto. <strong>Rojo</strong>: por repasar. <strong>Naranjo</strong>: lo que estás haciendo.", "capturas": [{"clave": "piramidal", "titulo": "Neurona piramidal", "lamina": "golgi", "busca": "En la corteza cerebral (bajo la superficie del hemisferio) busca un soma con forma de triángulo, una dendrita larga que sube hacia la superficie y dendritas más cortas en la base.", "etiquetas": ["Soma", "Dendrita apical", "Dendritas basales", "Axón"], "preguntas": [{"p": "¿En qué zona del encéfalo encontraste la neurona piramidal?", "ops": ["Corteza cerebral", "Corteza del cerebelo", "Tronco encefálico", "Bulbo olfatorio"], "ok": 0, "pista": "Busca bajo la superficie de los hemisferios, no en la estructura con folias.", "exp": "Las neuronas piramidales están en la corteza cerebral (capas III y V) y también en el hipocampo."}, {"p": "¿Qué rasgo de la neurona piramidal le permite recibir información de varias capas de la corteza?", "ops": ["Su dendrita apical larga, que atraviesa varias capas", "Su soma pequeño y redondo", "Que no tiene dendritas basales", "Su axón corto que no sale de la corteza"], "ok": 0, "pista": "Fíjate en la prolongación que sube hacia la superficie.", "exp": "La dendrita apical cruza varias capas corticales y recibe aferencias de distintos orígenes; las basales integran información local."}, {"p": "¿Cuál es la función principal de las neuronas piramidales de la corteza motora?", "ops": ["Iniciar el movimiento voluntario: su axón forma el tracto corticoespinal", "Coordinar y ajustar la precisión del movimiento", "Llevar el tacto desde la piel hasta la médula", "Formar la mielina de los axones"], "ok": 0, "pista": "Piensa en la neurona de proyección cuyo axón baja hasta la médula.", "exp": "Son neuronas de proyección excitatorias (glutamatérgicas): su axón largo sale de la corteza y, en la corteza motora, forma el tracto corticoespinal (motoneurona superior)."}]}, {"clave": "purkinje", "titulo": "Célula de Purkinje", "lamina": "golgi", "busca": "En el cerebelo (la estructura posterior con folias), busca somas grandes ordenados en una sola hilera, con un árbol dendrítico en abanico que sube hacia la superficie de la folia y un axón que baja hacia su centro.", "etiquetas": ["Soma", "Árbol dendrítico", "Axón", "Sustancia blanca"], "preguntas": [{"p": "¿Dónde quedan los somas de Purkinje dentro de la folia?", "ops": ["En una hilera entre la capa externa (molecular) y la capa interna (granular)", "En la superficie de la folia, justo bajo la piamadre que la recubre", "En el centro de la folia, junto a los axones que entran y salen de ella", "Repartidos sin orden en todo el espesor de la corteza del cerebelo"], "ok": 0, "pista": "Sigue el árbol dendrítico hacia la superficie y el axón hacia el centro: el soma queda entre ambos.", "exp": "Forman una sola hilera (capa de Purkinje): su árbol dendrítico ocupa la capa molecular, por fuera, y su axón cruza la capa granular, por dentro."}, {"p": "El centro de cada folia, hacia donde baja el axón de Purkinje, casi no tiene somas. ¿Qué es esa zona?", "ops": ["Sustancia blanca: axones que entran y salen de la corteza del cerebelo", "Sustancia gris: somas pequeños que la plata no alcanzó a impregnar", "Capa molecular: dendritas de Purkinje que todavía no se ramifican", "Un ventrículo: espacio con líquido cefalorraquídeo entre las folias"], "ok": 0, "pista": "Piensa en qué viaja por el axón de Purkinje una vez que sale de la corteza.", "exp": "Es la sustancia blanca del cerebelo: axones mielinizados, como los de Purkinje (la única salida de la corteza cerebelosa) y las fibras que llegan a ella."}, {"p": "Bajo la hilera de Purkinje hay una capa que con Golgi se ve casi vacía. ¿Qué crees que hay ahí?", "ops": ["Muchísimas neuronas pequeñas que la plata no impregnó", "Sólo axones mielinizados, como en la sustancia blanca", "Un espacio vacío que dejó el tejido al deshidratarse", "Las dendritas de Purkinje antes de salir hacia afuera"], "ok": 0, "pista": "La plata impregna sólo algunas neuronas al azar: que no las veas no significa que no estén.", "exp": "Es la capa granular, la más poblada de todo el encéfalo: miles de millones de células granulares que el Golgi casi no tiñe. Lo comprobarás en el nivel III con cresil violeta."}, {"p": "¿Cuál es la función principal de la célula de Purkinje?", "ops": ["Integrar la información del cerebelo para coordinar y ajustar el movimiento", "Iniciar el movimiento voluntario desde la corteza motora del cerebro", "Llevar la sensibilidad de la piel y los músculos hasta la médula espinal", "Formar recuerdos nuevos de hechos y lugares junto con el hipocampo"], "ok": 0, "pista": "El cerebelo no inicia el movimiento: lo corrige.", "exp": "Es la única salida de la corteza cerebelosa y es inhibitoria (GABAérgica): ajusta la precisión y la coordinación del movimiento."}]}]}, {"n": 3, "tipo": "capturas", "titulo": "Cerebelo con Golgi y cresil violeta", "laminas": ["golgi", "cresil"], "instrucciones": "Mira la <strong>misma zona del cerebelo</strong> con dos tinciones (botones sobre la lámina) y compara: ¿qué se ve con una que no se ve con la otra, y por qué? En cada captura etiqueta las capas y responde. <strong>Verde</strong>: correcto. <strong>Rojo</strong>: por repasar. <strong>Naranjo</strong>: lo que estás haciendo.", "capturas": [{"clave": "cerebelo-golgi", "titulo": "Cerebelo con Golgi", "lamina": "golgi", "busca": "Con Golgi, enfoca una folia del cerebelo donde se vean sus capas: la molecular (externa, clara), la hilera de células de Purkinje y la granular (interna).", "etiquetas": ["Capa molecular", "Capa de Purkinje", "Capa granular"], "preguntas": [{"p": "En tu captura con Golgi la capa molecular se ve llena de ramas, pero casi sin somas. ¿De dónde vienen esas ramas?", "ops": ["Del árbol dendrítico de las células de Purkinje que está bajo ella", "De axones de la sustancia blanca que suben hasta la superficie", "De la glía que forma una red de soporte en la superficie del cerebelo", "De dendritas de las neuronas granulares que viven en esa misma capa"], "ok": 0, "pista": "Sigue una rama hacia abajo: ¿en qué soma termina?", "exp": "La capa molecular la ocupan los árboles dendríticos de Purkinje (y los axones de las granulares, que la cruzan como fibras paralelas). Tiene pocos somas: por eso se ve clara con cresil."}, {"p": "Con Golgi, ¿qué te permite reconocer una célula de Purkinje aunque esté sola?", "ops": ["Soma grande en la hilera media y árbol dendrítico en abanico hacia afuera", "Soma pequeño en la capa interna y pocas dendritas cortas en forma de garra", "Soma triangular y una dendrita apical que baja hacia la sustancia blanca", "Soma grande en la capa externa y un axón muy ramificado hacia la superficie"], "ok": 0, "pista": "Ubica la hilera de somas entre la capa clara y la capa interna.", "exp": "Golgi muestra la forma completa: soma grande en la capa de Purkinje y un árbol dendrítico aplanado que llena la capa molecular. Su axón baja hacia la sustancia blanca."}]}, {"clave": "cerebelo-cresil", "titulo": "Cerebelo con cresil violeta", "lamina": "cresil", "busca": "Cambia a Cresil violeta y busca la misma zona del cerebelo. Ahora la capa granular se ve repleta de núcleos pequeños y los somas de Purkinje se ven grandes, en hilera.", "etiquetas": ["Capa molecular", "Capa de Purkinje", "Capa granular", "Sustancia blanca"], "preguntas": [{"p": "Con cresil violeta ves los somas de Purkinje, pero no su árbol dendrítico. ¿Por qué?", "ops": ["El cresil marca el ARN de los cuerpos de Nissl, abundantes en el soma", "El cresil marca sólo núcleos: el citoplasma y las dendritas no se tiñen", "El cresil marca sólo glía: esos somas grandes son astrocitos, no neuronas", "El cresil disuelve las membranas y con ellas se pierden las dendritas finas"], "ok": 0, "pista": "Es un colorante básico: recuerda qué organelo del soma tiene mucho ARN (nivel II de «Partes de la neurona»).", "exp": "Se une al ARN del retículo endoplásmico rugoso (cuerpos de Nissl), que está en el soma y en las dendritas más gruesas; las ramas finas y el axón casi no tienen Nissl."}, {"p": "Al comparar tus dos capturas, ¿qué explica que la capa granular cambie tanto?", "ops": ["Es la misma capa: Golgi marca pocas células completas y cresil, todos los somas", "Son capas distintas: con Golgi enfocaste la molecular y con cresil la granular", "Es la misma capa: el cresil tiñe también la glía y el Golgi sólo las neuronas", "Son cortes distintos: el de cresil es más grueso y por eso muestra más células"], "ok": 0, "pista": "Piensa en cuántas neuronas marca cada tinción y qué parte de cada neurona.", "exp": "Las células granulares son las neuronas más numerosas del encéfalo: con cresil se ven todos sus somas; con Golgi sólo se impregnan unas pocas."}, {"p": "Si necesitas (a) contar las neuronas de una capa y (b) describir la forma de sus dendritas, ¿qué tinción eliges?", "ops": ["(a) Cresil, porque marca todos los somas; (b) Golgi, porque muestra la célula entera", "(a) Golgi, porque marca todos los somas; (b) cresil, porque muestra la célula entera", "(a) Cresil, porque marca todos los somas; (b) cresil, porque también tiñe dendritas", "(a) Golgi, porque marca pocas células; (b) Golgi, porque muestra la célula entera"], "ok": 0, "pista": "Una tinción muestra todos los somas sin prolongaciones; la otra, pocas neuronas pero completas.", "exp": "Cresil (Nissl): todos los somas, ideal para contar y ver capas. Golgi: pocas neuronas completas, ideal para estudiar su morfología."}]}]}]}', 'Trabajo de la lámina', 1);
-- Nivel I (orientación): estructuras del esquema img/corte-sagital-rata.jpg
INSERT OR IGNORE INTO labeling_parts (actividad_id, nombre, x_pct, y_pct, descripcion, funcion, sinonimos, box_x_pct, box_y_pct, orden, forma) VALUES
  (1, 'Bulbo olfatorio', 10.0, 45.5,
      'Recibe los axones de las neuronas olfatorias, que son bipolares. En la rata es grande: el olfato es su sentido principal.',
      'Primera estación de la vía olfatoria: recibe y procesa la información de los olores.',
      'bulbo olfativo|bulbos olfatorios|bulbo', 6, 26, 1, 'elipse:13.7,47.0,7.9,8.4'),
  (1, 'Corteza cerebral', 37.3, 20.5,
      'En la rata es lisa, sin circunvoluciones. Aquí encontrarás las neuronas piramidales del nivel II.',
      'Funciones superiores: percepción, lenguaje, planificación y movimiento voluntario.',
      '+neocorteza|corteza|cortex|isocorteza|corteza del cerebro|cerebro', 30, 7, 2, NULL),
  (1, 'Hipocampo', 56.7, 34.3,
      'En el corte sagital se ve como una banda curva bajo la corteza, en forma de C. También tiene neuronas piramidales.',
      'Formación de nuevas memorias (memoria declarativa) y orientación espacial.',
      'hipocampos|formacion hipocampal|hippocampus', 60, 8, 3, NULL),
  (1, 'Cerebelo', 83.3, 47.0,
      'Sus pliegues se llaman folias; la sustancia blanca interna forma el «árbol de la vida». En su corteza están las células de Purkinje.',
      'Coordinar y ajustar la precisión del movimiento, la postura y el equilibrio.',
      'cerebelos|cerebellum', 92, 26, 4, 'elipse:81.0,47.5,12.0,17.5'),
  (1, 'Tronco encefálico', 76.7, 72.0,
      'Incluye mesencéfalo, puente y bulbo raquídeo; allí están los núcleos de los nervios craneales. Continúa con la médula espinal.',
      'Conecta el encéfalo con la médula espinal y controla funciones vitales como la respiración y la frecuencia cardíaca.',
      '+tronco cerebral|tronco|tallo cerebral|tronco del encefalo|troncoencefalo|tronco encefalico', 80, 90, 5, NULL);
INSERT OR IGNORE INTO actividad_carrera (actividad_id, carrera_id, descripcion, orden) VALUES
  (1, 1, 'En Fonoaudiología, las neuronas piramidales son relevantes por su rol en el área de Broca (producción del lenguaje) y el área de Wernicke (comprensión); el cerebelo coordina la articulación del habla.', 1),
  (1, 2, 'En Terapia Ocupacional, las piramidales de la corteza motora inician el movimiento voluntario (tracto corticoespinal) y las células de Purkinje lo coordinan y ajustan: su lesión altera la precisión de las actividades de la vida diaria.', 2);

