.02],[57.43,60.33],[61.15,70.58],[64.71,74.21],[69.04,75.87],[72.91,76.03],[77.09,74.88],[80.5,72.56],[82.66,69.75],[83.75,66.94],[83.9,63.47],[83.13,60.33],[81.42,57.36],[79.1,55.04],[69.97,50.41],[67.65,47.27],[66.87,43.31],[67.18,35.87],[68.89,29.75],[70.59,26.78],[76.47,21.16]]]}},"punto":[15.48,42.15],"pista":"Es la zona pálida que rodea a la mariposa.","exp":"Axones mielinizados que suben y bajan por la médula (los cordones)."},{"clave":"canal-central","nombre":"Canal central","zona":{"e":[[51.39,51.07,2.48,2.64]]},"punto":[51.39,51.07],"pista":"Es el pequeño orificio en el centro de la mariposa.","exp":"Resto del tubo neural, revestido por células ependimarias; tiene líquido cefalorraquídeo."},{"clave":"fisura-ventral","nombre":"Fisura media ventral","zona":{"r":[[47.37,71.9,8.36,23.97]]},"punto":[51.39,86.78],"pista":"Es la hendidura ancha del borde, en la línea media, abajo.","exp":"Marca el lado ventral: es más ancha y profunda que el tabique dorsal."},{"clave":"tabique-dorsal","nombre":"Tabique medio dorsal","zona":{"r":[[48.61,4.13,5.57,40.5]]},"punto":[51.39,14.05],"pista":"Es la línea delgada que baja desde el borde de arriba hasta la mariposa.","exp":"Divide en dos los cordones dorsales; marca el lado dorsal."}],"orden":[],"preguntas":[{"p":"¿Cómo reconoces el lado ventral de este corte?","ops":["Por la fisura media ventral y las astas anchas con somas grandes","Por el tabique medio dorsal y las astas delgadas sin somas grandes","Por el canal central, que siempre queda junto al borde ventral","Por la sustancia blanca, que sólo rodea a la médula por ese lado"],"ok":0,"pista":"Busca la hendidura del borde y el asta donde están las neuronas más grandes.","exp":"El lado ventral tiene la fisura media ventral (una hendidura profunda) y las astas ventrales, anchas, con las motoneuronas. El dorsal tiene un tabique delgado y astas dorsales angostas."},{"p":"Según tu orientación, ¿qué llega al asta dorsal y qué sale del asta ventral?","ops":["Llega información sensitiva por la raíz dorsal y salen órdenes motoras por la ventral","Llegan órdenes motoras por la raíz dorsal y sale información sensitiva por la ventral","Llega líquido cefalorraquídeo del canal y sale mielina hacia la sustancia blanca","Llegan axones del encéfalo por la raíz dorsal y salen hacia el encéfalo por la ventral"],"ok":0,"pista":"Dorsal = entrada sensitiva; ventral = salida motora.","exp":"Es la ley de Bell-Magendie: la raíz dorsal es sensitiva (entrada) y la ventral es motora (salida). Por eso el asta dorsal recibe y el asta ventral, con sus motoneuronas, envía."}]}]},{"n":2,"tipo":"rompecabezas","titulo":"Los extremos del arco","tablero":"img/reflejo/tablero-huecos.jpg","huecos":true,"instrucciones":"La médula ya está. Completa los huecos punteados: toca un hueco y elige su pieza, o arrastra la pieza a cualquier parte de su hueco. Primero el lado <strong>sensitivo</strong> (lo que trae la información) y después el <strong>motor</strong> (lo que la lleva al músculo). <strong>Verde</strong>: correcto. <strong>Rojo</strong>: por repasar. <strong>Naranjo</strong>: lo que estás haciendo.","grupos":{"sensitivo":"1. Lado sensitivo: receptores → nervio → ganglio → raíz dorsal","motor":"2. Lado motor: raíz ventral → nervio → músculo"},"piezas":[{"clave":"piel","nombre":"Piel","grupo":"sensitivo","img":"img/reflejo/piezas/piel.webp","caja":[1.76,8.5,25.65,21.97],"zona":{"p":[[[1.82,14.16],[1.89,28.22],[2.47,29.49],[19.53,30.27],[21.35,29.3],[24.54,29.3],[27.28,24.61],[27.28,10.74],[26.5,9.77],[22.33,9.77],[19.99,9.08],[16.02,9.77],[13.35,8.98],[10.29,9.38],[7.36,8.59],[5.99,9.38]]]},"pista":"El bloque de arriba, con sus capas.","exp":"Tiene receptores: las terminaciones libres de dolor y temperatura inician el reflejo de retirada."},{"clave":"musculo-extensor","nombre":"Músculo con huso (extensor)","grupo":"sensitivo","img":"img/reflejo/piezas/musculo-extensor.webp","caja":[1.17,39.55,36.59,21.48],"zona":{"p":[[[1.24,48.73],[1.37,50.29],[3.65,51.17],[8.14,56.25],[10.61,58.4],[13.54,59.96],[17.51,60.84],[21.35,60.74],[25.0,59.77],[27.34,58.5],[33.14,53.81],[36.33,53.03],[36.46,53.91],[37.63,53.12],[37.57,47.27],[35.87,47.95],[33.66,47.56],[28.26,43.16],[28.71,42.77],[27.41,41.89],[25.85,41.89],[22.59,40.43],[19.73,39.75],[16.28,39.65],[13.54,40.14],[9.9,41.6],[5.21,44.73],[3.45,45.12],[1.82,44.53],[1.63,45.61],[2.15,46.09],[1.5,46.58],[1.82,47.07],[1.3,47.85],[1.5,48.24]]]},"pista":"El músculo del medio: en su interior se ve el huso.","exp":"Su huso muscular detecta el estiramiento: es el receptor del reflejo rotuliano. Además es efector (se contrae)."},{"clave":"nervio","nombre":"Nervio espinal y sus ramos","grupo":"sensitivo","img":"img/reflejo/piezas/nervio.webp","caja":[16.93,23.73,41.73,40.23],"zona":{"p":[[[16.99,30.47],[21.22,30.96],[24.48,32.71],[26.11,34.96],[27.8,38.38],[29.62,40.53],[27.47,41.7],[28.84,42.68],[31.9,42.38],[39.39,45.21],[37.7,47.17],[37.7,53.03],[36.33,54.1],[35.42,57.71],[34.38,59.86],[31.38,62.89],[32.75,63.77],[34.51,62.3],[36.07,59.96],[37.3,56.74],[38.74,51.17],[40.76,47.95],[42.32,46.68],[43.82,46.09],[46.22,46.19],[47.92,46.78],[47.98,44.24],[47.53,43.85],[48.37,41.6],[50.65,38.57],[51.5,37.99],[55.34,38.38],[57.88,37.11],[55.47,37.79],[53.39,37.21],[51.82,35.84],[50.39,33.01],[48.57,35.94],[44.27,40.33],[41.02,41.5],[36.98,41.5],[33.46,40.43],[30.08,38.28],[28.12,35.64],[25.98,31.84],[24.09,30.08],[24.35,29.39],[21.35,29.39],[19.53,30.37]]]},"pista":"La vía que se ramifica hacia la piel y los músculos.","exp":"Une la raíz dorsal y la ventral: es mixto (sensitivo y motor). Sus ramos llegan a la piel y a los músculos."},{"clave":"ganglio","nombre":"Ganglio de la raíz dorsal","grupo":"sensitivo","img":"img/reflejo/piezas/ganglio.webp","caja":[50.39,23.73,10.55,14.16],"zona":{"p":[[[59.11,25.2],[57.23,23.83],[55.4,24.61],[53.45,26.37],[51.82,28.91],[50.46,32.71],[51.24,34.86],[53.06,36.91],[55.47,37.7],[57.55,37.11],[59.11,35.74],[60.48,32.91],[60.81,30.47],[60.48,28.03]]]},"pista":"El abultamiento entre el nervio y la médula, del lado de arriba.","exp":"Tiene los somas de las neuronas sensitivas (pseudounipolares) rodeados de células satélite."},{"clave":"raiz-dorsal","nombre":"Raíz dorsal","grupo":"sensitivo","img":"img/reflejo/piezas/raiz-dorsal.webp","caja":[58.53,21.29,10.22,10.06],"zona":{"p":[[[68.62,21.68],[66.15,21.48],[61.39,24.61],[60.42,24.61],[58.92,23.83],[58.59,23.93],[58.59,24.51],[60.16,26.86],[61.0,31.15],[62.37,28.42],[64.45,26.66]]]},"pista":"Une el ganglio con el lado dorsal de la médula.","exp":"Lleva la rama central de las sensitivas hasta el asta dorsal."},{"clave":"raiz-ventral","nombre":"Raíz ventral","grupo":"motor","img":"img/reflejo/piezas/raiz-ventral.webp","caja":[47.98,44.14,14.78,17.38],"zona":{"p":[[[48.05,44.34],[48.05,46.88],[49.22,47.85],[53.71,55.18],[56.12,57.32],[60.55,59.57],[62.04,61.33],[62.63,61.23],[60.87,56.74],[59.9,52.73],[59.83,54.59],[57.94,54.69],[56.38,54.0],[54.36,52.15],[50.65,46.09]]]},"pista":"Sale del lado ventral de la médula, el de las astas anchas.","exp":"Lleva los axones de las motoneuronas desde el asta ventral hacia el nervio."},{"clave":"musculo-flexor","nombre":"Músculo flexor","grupo":"motor","img":"img/reflejo/piezas/musculo-flexor.webp","caja":[1.95,62.79,43.88,27.73],"zona":{"p":[[[2.15,69.43],[2.15,70.7],[5.6,73.54],[9.96,80.27],[13.15,84.38],[17.06,87.79],[20.7,89.65],[24.02,90.33],[28.32,90.14],[38.8,86.43],[41.21,86.62],[44.47,87.79],[44.66,86.13],[45.05,85.55],[45.12,83.98],[45.44,83.59],[45.31,83.01],[45.7,82.62],[41.34,80.27],[35.09,70.51],[32.42,67.87],[30.21,66.41],[30.21,65.72],[32.68,63.87],[31.38,62.99],[27.99,65.43],[24.02,63.57],[20.12,62.89],[14.65,63.48],[7.75,66.6],[5.92,66.5],[3.52,65.33],[3.58,65.92],[3.12,66.31],[3.39,66.7],[2.86,67.19],[3.19,67.68],[2.41,68.36],[2.6,68.75]]]},"pista":"El músculo de abajo, al final del ramo que baja.","exp":"Efector del reflejo de retirada: al contraerse, aleja la extremidad del estímulo."}],"preguntas":[{"p":"¿Por qué la raíz dorsal tiene un ganglio y la ventral no?","ops":["Los somas sensitivos están fuera de la médula; los motores, dentro","La raíz dorsal es más larga y necesita un relevo en el camino","En el ganglio ocurre la sinapsis entre la sensitiva y la motora","La raíz ventral no lleva axones, sólo glía y vasos sanguíneos"],"ok":0,"pista":"¿Dónde están los somas de las motoneuronas? ¿Y los de las sensitivas?","exp":"El ganglio agrupa los somas de las neuronas sensitivas, fuera del SNC. Los somas motores están dentro, en el asta ventral, así que la raíz ventral sólo lleva axones. En el ganglio no hay sinapsis."},{"p":"El nervio espinal lleva juntos axones sensitivos y motores. ¿Cómo se clasifica?","ops":["Mixto: lleva fibras sensitivas y motoras a la vez","Sensitivo: sólo lleva información hacia la médula","Motor: sólo lleva las órdenes hacia los músculos","Autónomo: sólo controla las vísceras y glándulas"],"ok":0,"pista":"Recuerda qué raíces se unen para formarlo.","exp":"Todos los nervios espinales son mixtos: reciben fibras de la raíz dorsal (sensitivas) y de la ventral (motoras). Por eso una lesión del nervio afecta la sensibilidad y la fuerza a la vez."}]},{"n":3,"tipo":"circuito","titulo":"Reflejo rotuliano","fondo":"img/reflejo/esquema-base.jpg","vb":[1536,1024],"instrucciones":"Al golpear el tendón se estira el extensor. <strong>1. Ubica</strong> cada neurona tocando dónde está su soma (aparece al acertar). <strong>2. Conecta</strong> las dos vías tocando las neuronas en el orden en que viaja la información. <strong>3. Lupas</strong>: toca cada 🔍 y responde. <strong>4. Preguntas</strong>. <strong>Verde</strong>: correcto. <strong>Rojo</strong>: por repasar. <strong>Naranjo</strong>: lo que estás haciendo.","circuitos":[{"clave":"rotuliano","titulo":"Reflejo rotuliano","sub":"con inhibición recíproca","estimulo":"Golpe del martillo en el tendón bajo la rótula: el cuádriceps (extensor) se estira.","receptor":"Huso muscular","efector":"Extensor","piezas":[{"clave":"sensitiva","nombre":"Neurona sensitiva del huso","detalle":"pseudounipolar","icono":"Pseudounipolar","color":"#2563EB","zona":{"e":[[55.47,30.86,5.34,7.03]]},"zona_nombre":"Ganglio de la raíz dorsal","punto":[55.34,29.1],"pista":"Su soma está fuera de la médula, en el abultamiento de la raíz dorsal.","exp":"Su soma está en el ganglio de la raíz dorsal. La rama periférica trae la señal del receptor y la rama central entra a la médula por la raíz dorsal, sin sinapsis en el ganglio.","trazo":{"color":"#2563EB","ico":"Pseudounipolar","soma":[850,298,24],"d":["M292,500 C320,470 360,448 410,438 S560,432 610,440 S700,425 740,400 S810,345 850,338","M850,338 L850,322","M850,338 C880,315 920,285 960,268 S1040,238 1068,250 C1085,262 1092,285 1105,310 S1128,345 1132,370 C1136,420 1110,480 1080,512"],"fino":["M262,492 q8,-14 16,0 q8,14 16,0 q8,-14 16,0","M1133,395 C1145,420 1155,440 1160,458"],"botones":[[1080,512,7],[1069,509,6],[1088,519,6],[1160,462,6]]}},{"clave":"motora-ext","nombre":"Motoneurona del extensor","detalle":"multipolar","icono":"Motoneurona","color":"#DC2626","zona":{"p":[[[67.84,48.83],[66.67,50.78],[66.08,53.22],[66.34,56.45],[67.64,59.08],[69.34,60.45],[71.81,60.84],[73.83,59.96],[75.26,58.2],[77.21,51.86],[77.21,47.46],[69.4,47.46]]]},"zona_nombre":"Asta ventral","punto":[68.03,53.22],"pista":"Busca el asta ancha de la mariposa, la del lado de la raíz ventral.","exp":"Su soma está en el asta ventral y su axón sale por la raíz ventral y el nervio hasta la placa motora: es la vía final común. Inerva al extensor, el mismo músculo que se estiró.","trazo":{"color":"#DC2626","ico":"Motoneurona","soma":[1045,545,26],"d":["M1045,545 C1020,565 990,580 962,590 C905,572 855,530 800,494 S705,452 620,450 S500,438 470,440 C450,445 438,460 430,476"],"fino":[],"botones":[[424,484,6],[436,486,6],[430,492,6]]}},{"clave":"inhib","nombre":"Interneurona inhibitoria","detalle":"multipolar","icono":"Multipolar","color":"#7C3AED","zona":{"e":[[76.5,44.73,3.78,4.3]],"p":[]},"zona_nombre":"Sustancia gris intermedia","punto":[76.17,45.9],"pista":"Está en la sustancia gris, entre el asta dorsal y la ventral, cerca del canal central.","exp":"Recibe una colateral de la sensitiva y frena a la motoneurona del músculo antagonista.","trazo":{"color":"#7C3AED","ico":"Multipolar","soma":[1170,470,18],"d":["M1165,488 C1162,515 1155,540 1140,562"],"fino":[],"botones":[[1138,565,6],[1148,566,6]]}},{"clave":"motora-flex","nombre":"Motoneurona del flexor","detalle":"multipolar","icono":"Motoneurona","color":"#EA580C","zona":{"p":[[[67.84,48.83],[66.67,50.78],[66.08,53.22],[66.34,56.45],[67.64,59.08],[69.34,60.45],[71.81,60.84],[73.83,59.96],[75.26,58.2],[77.21,51.86],[77.21,47.46],[69.4,47.46]]]},"zona_nombre":"Asta ventral","punto":[72.79,57.13],"pista":"Busca el asta ancha de la mariposa, la del lado de la raíz ventral.","exp":"Su soma está en el asta ventral y su axón sale por la raíz ventral y el nervio hasta la placa motora: es la vía final común. Inerva al flexor, el antagonista.","trazo":{"color":"#EA580C","ico":"Motoneurona","soma":[1118,585,22],"d":["M1118,585 L1100,590 C1050,600 1000,598 965,598 C905,582 855,542 800,504 S705,462 625,460 C600,480 590,520 575,580 S500,650 430,690"],"fino":["M430,690 C390,700 340,705 300,715 M430,690 C400,715 360,735 325,755 M430,690 C415,730 400,760 388,790 M430,690 C440,730 450,760 457,793"],"botones":[[300,715,6],[325,755,6],[388,790,6],[457,793,6]]}}],"vias":[{"titulo":"Vía directa","orden":["sensitiva","motora-ext"],"pista":"Empieza por la neurona que recibe del huso; ¿con quién hace sinapsis directo?","exp":"Huso → sensitiva (ganglio, raíz dorsal) → motoneurona del extensor (asta ventral, raíz ventral) → el extensor se contrae: una sola sinapsis central.","ruta":"M292,500 C320,470 360,448 410,438 S560,432 610,440 S700,425 740,400 S810,345 850,338 C880,315 920,285 960,268 S1040,238 1068,250 C1085,262 1092,285 1105,310 S1128,345 1132,370 C1136,420 1110,480 1080,512 L1045,545 C1020,565 990,580 962,590 C905,572 855,530 800,494 S705,452 620,450 S500,438 470,440 C450,445 438,460 430,476"},{"titulo":"Inhibición recíproca","orden":["sensitiva","inhib","motora-flex"],"inhibe":"motora-flex","pista":"La colateral de la sensitiva pasa por una interneurona antes de llegar al flexor.","exp":"Sensitiva → interneurona inhibitoria → motoneurona del flexor, que queda frenada: el antagonista se relaja.","ruta":"M292,500 C320,470 360,448 410,438 S560,432 610,440 S700,425 740,400 S810,345 850,338 C880,315 920,285 960,268 S1040,238 1068,250 C1085,262 1092,285 1105,310 S1128,345 1132,370 L1133,395 C1145,420 1155,440 1160,458 L1170,470 L1165,488 C1162,515 1155,540 1140,562 L1118,585"}],"lupas":[{"clave":"huso","titulo":"Huso muscular","img":"img/reflejo/huso-muscular.jpg","x":262,"y":520,"preguntas":[{"p":"¿Qué estímulo activa a la terminación azul enrollada en el huso?","ops":["El estiramiento del músculo, que deforma las fibras intrafusales","La contracción voluntaria del músculo, que acorta las fibras","El dolor del golpe del martillo sobre la piel de la rodilla","La acetilcolina liberada por la motoneurona sobre el huso"],"ok":0,"pista":"Piensa en qué le hace el martillo al tendón y al músculo.","exp":"El golpe estira el tendón y el cuádriceps; el estiramiento deforma la terminación anuloespiral y abre canales iónicos: nace el potencial en la neurona sensitiva."},{"p":"¿En qué se diferencian las fibras del huso de las del resto del músculo?","ops":["Son intrafusales: detectan longitud y casi no aportan fuerza","Son extrafusales: generan casi toda la fuerza del músculo","Son nerviosas: forman parte del axón de la neurona sensitiva","Son tendinosas: unen el músculo con el hueso de la rótula"],"ok":0,"pista":"El huso está dentro de una cápsula.","exp":"Las fibras intrafusales están dentro de la cápsula del huso y funcionan como sensor de longitud; las extrafusales hacen la fuerza."}]},{"clave":"excitatoria","titulo":"Sinapsis excitatoria (azul → roja)","img":"img/reflejo/sinapsis-excitatoria.jpg","x":1010,"y":500,"preguntas":[{"p":"¿Qué neurotransmisor libera la sensitiva sobre la motoneurona?","ops":["Glutamato, que excita a la motoneurona","GABA, que inhibe a la motoneurona","Acetilcolina, que contrae al músculo","Glicina, que frena a la motoneurona"],"ok":0,"pista":"Es el principal neurotransmisor excitatorio del sistema nervioso central.","exp":"La sensitiva libera glutamato: abre canales de Na⁺ en la motoneurona, que se despolariza y dispara."},{"p":"En la lupa, ¿qué lado es presináptico y cuál postsináptico?","ops":["Presináptico: el botón azul con vesículas; postsináptico: la roja","Presináptico: la roja con receptores; postsináptico: el botón azul","Ambos son presinápticos, porque los dos liberan vesículas","Ninguno: la hendidura es una unión directa entre citoplasmas"],"ok":0,"pista":"Las vesículas están en la neurona que envía.","exp":"El botón de la sensitiva (azul) tiene las vesículas y libera; la motoneurona (roja) tiene los receptores. Entre ambos queda la hendidura sináptica."}]},{"clave":"inhibitoria","titulo":"Sinapsis inhibitoria (morada → naranja)","img":"img/reflejo/sinapsis-inhibitoria.jpg","x":1188,"y":600,"preguntas":[{"p":"¿Qué hace la interneurona morada sobre la motoneurona naranja?","ops":["La inhibe con glicina o GABA y el flexor se relaja","La excita con glutamato y el flexor se contrae","La inhibe con acetilcolina y el extensor se relaja","La excita con glicina y el extensor se contrae"],"ok":0,"pista":"Mira el color de la lupa: es la sinapsis inhibitoria.","exp":"La interneurona inhibitoria libera glicina (o GABA), abre canales de Cl⁻ e hiperpolariza a la motoneurona del flexor: el músculo antagonista se relaja."},{"p":"¿Para qué sirve frenar al flexor mientras se contrae el extensor?","ops":["Para que el antagonista no se oponga y la pierna se extienda","Para que el flexor descanse y se recupere del golpe del martillo","Para que la señal suba al encéfalo antes de contraer el extensor","Para que el huso del flexor deje de estirarse y se apague"],"ok":0,"pista":"Si los dos músculos se contrajeran a la vez, ¿se movería la rodilla?","exp":"Es la inhibición recíproca: mientras el agonista se contrae, el antagonista se relaja y el movimiento es eficiente."}]},{"clave":"placa","titulo":"Placa motora","img":"img/reflejo/placa-motora.jpg","x":470,"y":500,"preguntas":[{"p":"¿Qué neurotransmisor libera la motoneurona en la placa motora?","ops":["Acetilcolina, que abre canales en la fibra muscular","Glutamato, que abre canales en la fibra muscular","Glicina, que relaja la fibra muscular al instante","Noradrenalina, que acelera la fibra muscular"],"ok":0,"pista":"Es el mismo neurotransmisor de todas las uniones neuromusculares del músculo esquelético.","exp":"La acetilcolina se une a receptores nicotínicos de la fibra muscular, la despolariza y desencadena la contracción."},{"p":"¿Para qué sirven los pliegues de la membrana muscular bajo el botón?","ops":["Aumentan la superficie con receptores de acetilcolina","Guardan las vesículas de acetilcolina de la motoneurona","Aíslan la fibra para que el impulso no se escape","Producen la mielina que envuelve al axón motor"],"ok":0,"pista":"Fíjate qué hay en la membrana de los pliegues.","exp":"Los pliegues de la unión neuromuscular multiplican la superficie con receptores: cada impulso libera acetilcolina suficiente para contraer la fibra."}]}],"preguntas":[{"p":"¿Cómo se clasifica el reflejo rotuliano?","ops":["Monosináptico: una sola sinapsis central, sin interneurona","Polisináptico: varias sinapsis centrales, con interneuronas","Monosináptico: una sola neurona, que es sensitiva y motora","Polisináptico: varias sinapsis dentro del ganglio dorsal"],"ok":0,"pista":"Cuenta las sinapsis entre la sensitiva y la motoneurona.","exp":"Es monosináptico: es el reflejo más rápido. Por eso se usa para evaluar el arco reflejo (nervio, raíz, segmento medular y músculo)."},{"p":"Si la vía directa es monosináptica, ¿por qué hay una interneurona en este reflejo?","ops":["Frena al antagonista: es otra vía, en paralelo a la directa","Retrasa la contracción del extensor para que sea más suave","Lleva la información del huso hacia el encéfalo para sentirla","Reemplaza a la motoneurona cuando el golpe es muy fuerte"],"ok":0,"pista":"Mira hacia qué motoneurona va la morada.","exp":"La vía directa (sensitiva → motoneurona del extensor) tiene una sola sinapsis. La interneurona está en una vía paralela que inhibe al flexor."}]}]},{"n":4,"tipo":"circuito","titulo":"Reflejo de retirada","fondo":"img/reflejo/esquema-base.jpg","vb":[1536,1024],"instrucciones":"Pisas un clavo. Las dos motoneuronas ya están. <strong>1. Ubica</strong> la sensitiva y las dos interneuronas. <strong>2. Conecta</strong> las dos vías. <strong>3. Lupas</strong>. <strong>4. Preguntas</strong>. <strong>Verde</strong>: correcto. <strong>Rojo</strong>: por repasar. <strong>Naranjo</strong>: lo que estás haciendo.","circuitos":[{"clave":"retirada","titulo":"Reflejo de retirada","sub":"polisináptico","estimulo":"Pisas un clavo: el pie se retira antes de que sientas el dolor.","receptor":"Nociceptor (piel)","efector":"Flexor","piezas":[{"clave":"sensitiva","nombre":"Neurona sensitiva del dolor","detalle":"pseudounipolar","icono":"Pseudounipolar","color":"#0891B2","zona":{"e":[[55.47,30.86,5.34,7.03]]},"zona_nombre":"Ganglio de la raíz dorsal","punto":[55.34,29.1],"pista":"Su soma está fuera de la médula, en el abultamiento de la raíz dorsal.","exp":"Su soma está en el ganglio de la raíz dorsal. La rama periférica trae la señal del receptor y la rama central entra a la médula por la raíz dorsal, sin sinapsis en el ganglio. Sus terminaciones libres en la piel son nociceptores.","trazo":{"color":"#0891B2","ico":"Pseudounipolar","soma":[850,298,24],"d":["M228,285 C280,300 340,305 375,325 S430,395 470,418 S570,430 610,438 S700,420 740,395 S810,345 850,338","M850,338 L850,322","M850,338 C880,315 920,285 960,268 S1040,238 1068,250 C1085,262 1092,285 1105,310 L1116,346"],"fino":["M228,285 L83,213 M228,285 L114,208 M228,285 L157,206 M228,285 L190,204 M228,285 L235,203 M228,285 L277,209","M1105,310 C1135,345 1160,400 1176,430"],"botones":[[83,213,5],[114,208,5],[157,206,5],[190,204,5],[235,203,5],[277,209,5],[1118,350,7],[1109,345,6],[1176,433,6]]}},{"clave":"exc","nombre":"Interneurona excitatoria","detalle":"multipolar","icono":"Multipolar","color":"#16A34A","zona":{"p":[[[69.27,28.12],[69.08,28.42],[71.81,32.03],[72.4,33.69],[73.05,37.21],[73.18,41.41],[76.56,41.41],[76.56,40.43],[73.7,31.05],[72.59,29.59],[69.86,27.64],[69.6,28.32]]]},"zona_nombre":"Asta dorsal","punto":[73.89,36.62],"pista":"Está en el asta dorsal, donde termina la sensitiva del dolor.","exp":"Recibe a la sensitiva en el asta dorsal y excita a la motoneurona del flexor.","trazo":{"color":"#16A34A","ico":"Multipolar","soma":[1135,375,18],"d":["M1135,393 C1142,450 1135,520 1122,562"],"fino":[],"botones":[[1120,565,6],[1130,566,6]]}},{"clave":"inhib","nombre":"Interneurona inhibitoria","detalle":"multipolar","icono":"Multipolar","color":"#7C3AED","zona":{"e":[[76.5,44.73,3.78,4.3]],"p":[]},"zona_nombre":"Sustancia gris intermedia","punto":[77.15,43.46],"pista":"Está en la sustancia gris, entre el asta dorsal y la ventral, cerca del canal central.","exp":"Recibe una colateral de la sensitiva y frena a la motoneurona del extensor.","trazo":{"color":"#7C3AED","ico":"Multipolar","soma":[1185,445,18],"d":["M1173,458 C1150,490 1100,520 1070,533"],"fino":[],"botones":[[1068,536,6],[1072,528,6]]}},{"clave":"motora-flex","nombre":"Motoneurona del flexor","detalle":"multipolar","icono":"Motoneurona","color":"#EA580C","zona":{"p":[[[67.84,48.83],[66.67,50.78],[66.08,53.22],[66.34,56.45],[67.64,59.08],[69.34,60.45],[71.81,60.84],[73.83,59.96],[75.26,58.2],[77.21,51.86],[77.21,47.46],[69.4,47.46]]]},"zona_nombre":"Asta ventral","punto":[72.79,57.13],"pista":"Busca el asta ancha de la mariposa, la del lado de la raíz ventral.","exp":"Su soma está en el asta ventral y su axón sale por la raíz ventral y el nervio hasta la placa motora: es la vía final común.","trazo":{"color":"#EA580C","ico":"Motoneurona","soma":[1118,585,22],"d":["M1118,585 L1100,590 C1050,600 1000,598 965,598 C905,582 855,542 800,504 S705,462 625,460 C600,480 590,520 575,580 S500,650 430,690"],"fino":["M430,690 C390,700 340,705 300,715 M430,690 C400,715 360,735 325,755 M430,690 C415,730 400,760 388,790 M430,690 C440,730 450,760 457,793"],"botones":[[300,715,6],[325,755,6],[388,790,6],[457,793,6]]},"dada":true},{"clave":"motora-ext","nombre":"Motoneurona del extensor","detalle":"multipolar","icono":"Motoneurona","color":"#DC2626","zona":{"p":[[[67.84,48.83],[66.67,50.78],[66.08,53.22],[66.34,56.45],[67.64,59.08],[69.34,60.45],[71.81,60.84],[73.83,59.96],[75.26,58.2],[77.21,51.86],[77.21,47.46],[69.4,47.46]]]},"zona_nombre":"Asta ventral","punto":[68.03,53.22],"pista":"Busca el asta ancha de la mariposa, la del lado de la raíz ventral.","exp":"Su soma está en el asta ventral y su axón sale por la raíz ventral y el nervio hasta la placa motora: es la vía final común.","trazo":{"color":"#DC2626","ico":"Motoneurona","soma":[1045,545,26],"d":["M1045,545 C1020,565 990,580 962,590 C905,572 855,530 800,494 S705,452 620,450 S500,438 470,440 C450,445 438,460 430,476"],"fino":[],"botones":[[424,484,6],[436,486,6],[430,492,6]]},"dada":true}],"vias":[{"titulo":"Vía de la retirada","orden":["sensitiva","exc","motora-flex"],"pista":"Del nociceptor a la interneurona del asta dorsal, y de ahí al músculo que aleja el pie.","exp":"Nociceptor → sensitiva → interneurona excitatoria (asta dorsal) → motoneurona del flexor → el flexor retira el pie.","ruta":"M228,285 C280,300 340,305 375,325 S430,395 470,418 S570,430 610,438 S700,420 740,395 S810,345 850,338 C880,315 920,285 960,268 S1040,238 1068,250 C1085,262 1092,285 1105,310 L1118,350 L1135,375 L1135,393 C1142,450 1135,520 1122,562 L1118,585 L1100,590 C1050,600 1000,598 965,598 C905,582 855,542 800,504 S705,462 625,460 C600,480 590,520 575,580 S500,650 430,690 C400,715 360,735 325,755"},{"titulo":"Inhibición recíproca","orden":["sensitiva","inhib","motora-ext"],"inhibe":"motora-ext","pista":"Ahora hay que relajar al músculo que se opone a la flexión.","exp":"Sensitiva → interneurona inhibitoria → motoneurona del extensor, que queda frenada.","ruta":"M228,285 C280,300 340,305 375,325 S430,395 470,418 S570,430 610,438 S700,420 740,395 S810,345 850,338 C880,315 920,285 960,268 S1040,238 1068,250 C1085,262 1092,285 1105,310 C1135,345 1160,400 1176,430 L1185,445 L1173,458 C1150,490 1100,520 1070,533 L1045,545"}],"lupas":[{"clave":"excitatoria","titulo":"Sinapsis excitatoria (celeste → verde)","img":"img/reflejo/sinapsis-excitatoria.jpg","x":1172,"y":318,"preguntas":[{"p":"¿Qué cambia en la interneurona verde cuando la celeste libera glutamato?","ops":["Se despolariza y puede disparar hacia la motoneurona","Se hiperpolariza y deja de disparar hacia la motoneurona","Libera acetilcolina directamente sobre el músculo flexor","Envía el impulso de vuelta hacia la neurona sensitiva"],"ok":0,"pista":"El glutamato es excitatorio.","exp":"El glutamato abre canales catiónicos (entra Na⁺): la interneurona se despolariza y excita a la motoneurona del flexor."},{"p":"¿Por qué el reflejo de retirada tarda un poco más que el rotuliano?","ops":["Tiene más sinapsis: cada una suma un retardo sináptico","Su receptor está más lejos de la médula que el huso","Su motoneurona no tiene mielina y conduce muy lento","La señal pasa primero por el encéfalo antes de volver"],"ok":0,"pista":"Cuenta las sinapsis entre la sensitiva y la motoneurona.","exp":"Es polisináptico: cada sinapsis agrega cerca de 0,5–1 ms. Aun así no pasa por el encéfalo."}]},{"clave":"inhibitoria","titulo":"Sinapsis inhibitoria (morada → roja)","img":"img/reflejo/sinapsis-inhibitoria.jpg","x":1000,"y":505,"preguntas":[{"p":"En la retirada, ¿qué motoneurona queda inhibida y por qué?","ops":["La del extensor, para que no se oponga al flexor","La del flexor, para que la pierna no se mueva","La del extensor, para que el huso deje de estirarse","La del flexor, para proteger el músculo del dolor"],"ok":0,"pista":"Ahora el que se contrae es el flexor.","exp":"Se invierte el rotuliano: el flexor se contrae y la interneurona inhibitoria frena al extensor (inhibición recíproca)."},{"p":"¿Qué distingue a una vesícula inhibitoria en la lupa?","ops":["Suele ser aplanada y contiene glicina o GABA","Es redonda y grande y contiene glutamato","Es densa y contiene acetilcolina para el músculo","No tiene contenido: sólo abre la hendidura"],"ok":0,"pista":"Compara la forma de las vesículas de las dos lupas sinápticas.","exp":"En la microscopía electrónica, las sinapsis inhibitorias suelen tener vesículas aplanadas (glicina o GABA) y las excitatorias, redondas (glutamato)."}]}],"preguntas":[{"p":"Al pisar el clavo contraes los flexores y a la vez se relajan los extensores. ¿Qué permite eso?","ops":["La interneurona, que reparte la señal: excita a unos y frena a otros","La sensitiva, que hace sinapsis directo con todos los músculos","La motoneurona, que envía órdenes opuestas por un solo axón","La raíz ventral, que separa las órdenes de contraer y relajar"],"ok":0,"pista":"¿Qué neurona tiene este circuito que el rotuliano no tiene?","exp":"Las interneuronas distribuyen la señal: excitan a las motoneuronas de los flexores e inhiben a las de los extensores (inervación recíproca). También pueden cruzar al otro lado para sostener el cuerpo."},{"p":"Retiras el pie antes de sentir el dolor. ¿Qué lo explica?","ops":["El circuito se cierra en la médula; la vía hacia el encéfalo es más larga","El dolor no llega al encéfalo hasta que el reflejo ya terminó","La interneurona bloquea el dolor mientras dura el movimiento","El encéfalo inicia el reflejo y después registra el dolor"],"ok":0,"pista":"¿Dónde se cierra el circuito que armaste? ¿Pasa por el encéfalo?","exp":"El reflejo se resuelve en el segmento medular. Al mismo tiempo, otras neuronas llevan la señal hacia el encéfalo, que la percibe como dolor un instante después."}]}]},{"n":5,"tipo":"circuito","titulo":"¿Dónde se cortó el arco?","fondo":"img/reflejo/esquema-base.jpg","vb":[1536,1024],"instrucciones":"Los tres pacientes tienen el <strong>reflejo rotuliano disminuido o ausente</strong>. Lee cada caso, tócalo y luego toca el sitio (A, B o C) donde está la lesión. Fíjate en lo que acompaña al reflejo: ¿falla la sensibilidad, la fuerza o ambas? <strong>Verde</strong>: correcto. <strong>Rojo</strong>: por repasar. <strong>Naranjo</strong>: lo que estás haciendo.","circuitos":[],"neuronas":[{"color":"#2563EB","ico":"Pseudounipolar","soma":[850,298,24],"d":["M292,500 C320,470 360,448 410,438 S560,432 610,440 S700,425 740,400 S810,345 850,338","M850,338 L850,322","M850,338 C880,315 920,285 960,268 S1040,238 1068,250 C1085,262 1092,285 1105,310 S1128,345 1132,370 C1136,420 1110,480 1080,512"],"fino":["M262,492 q8,-14 16,0 q8,14 16,0 q8,-14 16,0","M1133,395 C1145,420 1155,440 1160,458"],"botones":[[1080,512,7],[1069,509,6],[1088,519,6],[1160,462,6]]},{"color":"#DC2626","ico":"Motoneurona","soma":[1045,545,26],"d":["M1045,545 C1020,565 990,580 962,590 C905,572 855,530 800,494 S705,452 620,450 S500,438 470,440 C450,445 438,460 430,476"],"fino":[],"botones":[[424,484,6],[436,486,6],[430,492,6]]}],"cortes":{"titulo":"¿Dónde se cortó el arco?","sitios":[{"letra":"A","x":560,"y":445,"nombre":"Nervio (mixto)"},{"letra":"B","x":930,"y":262,"nombre":"Raíz dorsal y ganglio"},{"letra":"C","x":1045,"y":600,"nombre":"Asta ventral (motoneurona)"}],"casos":[{"titulo":"Hernia lumbar","caso":"Hombre de 45 años con una hernia del disco L3-L4 que comprime la raíz L4. Tiene dolor y hormigueo en la cara anterior de la pierna y el rotuliano disminuido; la fuerza para extender la rodilla está casi normal.","sitio":"B","respuesta":"Raíz dorsal (y su ganglio)","pista":"Predominan el dolor y el hormigueo: ¿qué parte del arco trae la información?","exp":"La hernia comprime la raíz posterior: falla la entrada sensitiva (dolor radicular en el dermatoma) y el reflejo disminuye, aunque la motoneurona esté sana. Si la compresión es intensa también puede haber algo de debilidad."},{"titulo":"Atrofia muscular espinal","caso":"Niña de 3 años con atrofia muscular espinal: debilidad y atrofia de los muslos, fasciculaciones y rotuliano ausente. Siente bien el tacto y el dolor.","sitio":"C","respuesta":"Asta ventral (motoneurona)","pista":"La sensibilidad está intacta y el músculo se atrofia. ¿Dónde están los somas de la vía final común?","exp":"La atrofia muscular espinal (como la poliomielitis) destruye las motoneuronas del asta ventral: se pierden el reflejo y la fuerza, el músculo se atrofia y fascicula, pero la sensibilidad queda intacta."},{"titulo":"Lesión del nervio femoral","caso":"Mujer de 60 años que, tras una cirugía de cadera, no puede extender la rodilla, no tiene rotuliano y no siente la cara anterior del muslo.","sitio":"A","respuesta":"Nervio (mixto)","pista":"Fallan a la vez la sensibilidad y la fuerza del mismo territorio.","exp":"El nervio femoral lleva juntas las fibras sensitivas y las motoras del cuádriceps: su lesión quita sensibilidad, fuerza y reflejo en su territorio."}]}}]}', NULL, 1);

-- Actividad 10: GLÍA DEL SNC. Nivel I esquema (identificación, labeling_parts; tarea B de Kaira Santos); nivel II práctica «elegir» con tarjetas e íconos (practica_niveles numero 2); niveles III-IV capturas
INSERT OR IGNORE INTO actividades (id, topic_id, slug, titulo, descripcion, tipo, activo, objetivo, mecanica, fuente) VALUES
  (10, 7, 'glia-snc', 'Glía del SNC',
       'Astrocito, oligodendrocito, microglía y célula ependimaria. Nivel I: identifícalas en un esquema. Nivel II: lee cada función y toca la tarjeta de su célula. Nivel III: canal central y sustancia blanca con H&E. Nivel IV: la motoneurona y la glía que la rodea con cresil violeta.',
       'lamina', 1, 'Describir la morfología y la función de la glía del SNC y reconocerla en cortes de médula espinal.', 'Identificar cada célula en un esquema; leer cada frase y tocar la tarjeta de la célula que describe; capturar, etiquetar y responder en dos láminas de médula.', 'Clase Células del sistema nervioso II 2026 · MHS-240 y UCSF-163 (histologyguide.com)');
INSERT OR IGNORE INTO actividad_recursos (actividad_id, tipo, url, caption, orden) VALUES
  (10, 'tareas', '{"laminas": {"mhs240": {"nombre": "H&E (conejo)", "url": "https://histologyguide.com/slideview/MHS-240-spinal-cord/06-slide-1.html?x=8910&y=6975&z=5.786", "caption": "Médula espinal de conejo — H&E (histologyguide.com)"}, "ucsf163": {"nombre": "Cresil violeta (gato)", "url": "https://histologyguide.com/slideview/UCSF-163-spinal-cord/06-slide-1.html?x=12976&y=9803&z=4.400", "caption": "Médula espinal de gato — cresil violeta (histologyguide.com)"}}, "niveles": [{"n": 1, "tipo": "identificar", "titulo": "Esquema", "img": "img/glia-snc.jpg"}, {"n": 2, "tipo": "practica", "titulo": "Cada célula, su función"}, {"n": 3, "tipo": "capturas", "titulo": "Canal central y sustancia blanca", "laminas": ["mhs240"], "instrucciones": "Para cada captura sigue los 4 pasos del panel: buscar y capturar, recortar, etiquetar y responder. <strong>Verde</strong>: correcto. <strong>Rojo</strong>: por repasar. <strong>Naranjo</strong>: lo que estás haciendo.", "capturas": [{"clave": "canal-central", "objeto": "la zona", "titulo": "Canal central", "lamina": "mhs240", "busca": "Acércate al centro de la médula, donde se cruzan las astas de la sustancia gris: busca un pequeño orificio y acércate hasta ver las células que forman su borde.", "etiquetas": ["Canal central", "Células ependimarias", "Sustancia gris"], "preguntas": [{"p": "Alrededor del canal central ves una sola capa de células cúbicas, bien juntas. ¿Qué te dice esa forma de ordenarse?", "ops": ["Forman un epitelio que reviste una cavidad con líquido cefalorraquídeo", "Son neuronas en fila que rodean la cavidad para detectar su presión", "Son oligodendrocitos en fila que mielinizan el borde del canal central", "Es tejido conectivo que sella el canal para que no salga el líquido"], "ok": 0, "pista": "Células en una sola capa, juntas y apoyadas sobre una cavidad: ¿qué tejido se organiza así?", "exp": "Es el epéndimo: un epitelio cúbico simple de células ependimarias que reviste el canal central y los ventrículos, por donde circula el líquido cefalorraquídeo."}, {"p": "El canal central se continúa con los ventrículos del encéfalo. ¿Qué contiene en una persona viva?", "ops": ["Líquido cefalorraquídeo, movido por los cilios ependimarios", "Sangre venosa, que drena la sustancia gris que rodea al canal", "Mielina, que se acumula mientras se forma la sustancia blanca", "Axones motores, que bajan desde el encéfalo por el centro"], "ok": 0, "pista": "Es el mismo líquido que llena los ventrículos.", "exp": "Contiene LCR. Las ependimarias lo mueven con sus cilios, regulan su composición y forman una barrera entre el LCR y el tejido nervioso (distinta de la barrera hematoencefálica)."}]}, {"clave": "sustancia-blanca", "objeto": "la zona", "titulo": "Sustancia blanca", "lamina": "mhs240", "busca": "Desde el centro, baja hacia el borde anterior de la médula, a la zona más clara y sin somas grandes. Acércate hasta ver núcleos pequeños y oscuros entre las fibras.", "etiquetas": ["Fibras nerviosas", "Núcleos de glía"], "preguntas": [{"p": "En la sustancia blanca ves muchos núcleos entre las fibras, pero casi no ves el citoplasma de esas células. ¿Por qué?", "ops": ["Su citoplasma es escaso y pálido; sólo el núcleo toma bien la hematoxilina", "No tienen citoplasma: en la sustancia blanca sólo hay núcleos libres", "Son núcleos de los axones cortados, que en H&E se ven sin citoplasma", "El citoplasma se disolvió al fijar la médula y quedó sólo el núcleo"], "ok": 0, "pista": "¿Qué parte de una célula tiene más ácidos nucleicos y por eso se tiñe más con hematoxilina?", "exp": "Con H&E se ve bien lo basófilo, como el núcleo. El citoplasma de la glía es poco y está repartido en prolongaciones finas que se pierden entre las fibras: por eso de la glía casi sólo se ven núcleos. Para ver la célula completa se usan tinciones especiales."}, {"p": "¿Cómo sabes que esos núcleos de la sustancia blanca no son de neuronas?", "ops": ["Son pequeños y oscuros, sin nucléolo marcado ni Nissl alrededor", "Son grandes y claros, con un nucléolo muy marcado en el centro", "Están dentro de los axones, y las neuronas nunca tienen núcleo ahí", "Se tiñen rosados con la eosina, y los de neurona se tiñen morados"], "ok": 0, "pista": "Compáralos con el núcleo de una neurona de la sustancia gris, en la misma captura.", "exp": "El núcleo de una neurona es grande, claro y con nucléolo visible, rodeado de citoplasma con Nissl. Los de la sustancia blanca son pequeños y oscuros: son sobre todo oligodendrocitos, ordenados en hileras entre las fibras que mielinizan."}, {"p": "¿Por qué esta zona se ve blanca a simple vista en el tejido fresco?", "ops": ["Por la mielina: sus lípidos envuelven a casi todos los axones", "Por los vasos: casi no tiene capilares que le aporten sangre", "Por la glía: sus células no tienen núcleo ni otros organelos", "Por el líquido: está empapada de LCR que viene del canal central"], "ok": 0, "pista": "Recuerda de qué está hecha la vaina que envuelve a los axones.", "exp": "La mielina tiene ~70 % de lípidos: le da a los tractos su color blanco. Al procesar el tejido para H&E esos lípidos se disuelven y la zona queda pálida."}]}]}, {"n": 4, "tipo": "capturas", "titulo": "Motoneurona y su glía", "laminas": ["ucsf163"], "instrucciones": "Para cada captura sigue los 4 pasos del panel: buscar y capturar, recortar, etiquetar y responder. <strong>Verde</strong>: correcto. <strong>Rojo</strong>: por repasar. <strong>Naranjo</strong>: lo que estás haciendo.", "capturas": [{"clave": "motoneurona", "titulo": "Motoneurona del asta ventral", "lamina": "ucsf163", "busca": "En la parte ancha y anterior de la sustancia gris, busca el soma más grande que encuentres y acércate hasta ver su núcleo, sus prolongaciones y lo que lo rodea.", "etiquetas": ["Soma", "Núcleo", "Cuerpos de Nissl", "Dendrita", "Núcleos de glía", "Neuropilo"], "preguntas": [{"p": "En tu motoneurona, una prolongación tiene grumos de Nissl en su base y otra sale de una zona clara, sin grumos. ¿Cuál es el axón?", "ops": ["La que sale de la zona clara: el cono axónico no tiene Nissl", "La que tiene grumos: el Nissl fabrica lo que el axón necesita", "Cualquiera de las dos: el Nissl se reparte al azar en el soma", "Ninguna: el cresil violeta no tiñe las prolongaciones del soma"], "ok": 0, "pista": "Recuerda hasta dónde llegan los cuerpos de Nissl (nivel II de «Partes de la neurona»).", "exp": "El Nissl está en el soma y en la base de las dendritas, pero no entra al cono axónico ni al axón. Por eso, con cresil violeta, la prolongación que nace de una zona clara es el axón."}, {"p": "Alrededor del soma de la motoneurona ves varios núcleos pequeños pegados a su borde. ¿Qué son?", "ops": ["Núcleos de glía que rodean a la neurona y la apoyan", "Núcleos extra de la motoneurona, que tiene varios", "Botones terminales de otras neuronas, teñidos de violeta", "Células de Schwann que forman mielina sobre el soma"], "ok": 0, "pista": "¿Una neurona tiene uno o varios núcleos? ¿Qué células acompañan a las neuronas en el SNC?", "exp": "Son núcleos de glía, sobre todo oligodendrocitos (satélites perineuronales) y astrocitos. La motoneurona tiene un solo núcleo, grande y claro, con nucléolo. Las células de Schwann sólo están en el SNP."}, {"p": "En la misma lámina, las neuronas del asta dorsal son mucho más pequeñas que la motoneurona. ¿Qué explica la diferencia?", "ops": ["La motoneurona mantiene un axón largo hasta el músculo y muchas dendritas", "Las del asta dorsal son células gliales, no neuronas, y por eso son chicas", "La motoneurona es grande porque recibe directo la información de la piel", "Las del asta dorsal se encogieron con el cresil violeta, y la ventral no"], "ok": 0, "pista": "Piensa hasta dónde llega el axón de cada una: ¿cuál tiene que mantener más «cable»?", "exp": "Un soma grande, con mucho Nissl, fabrica las proteínas que necesitan un axón muy largo y un árbol dendrítico amplio. Las neuronas del asta dorsal son en su mayoría interneuronas, de axón corto."}, {"p": "Entre los somas hay un fondo con pocos núcleos (neuropilo). ¿De qué está formado?", "ops": ["Dendritas, axones y prolongaciones de glía que se entrelazan", "Líquido cefalorraquídeo que se coaguló al fijar el tejido", "Mielina de la sustancia blanca que se mezcla con la gris", "Somas pequeños que el cresil violeta no alcanzó a teñir"], "ok": 0, "pista": "El cresil tiñe los somas. ¿Qué queda sin teñir entre ellos?", "exp": "El neuropilo es la red de dendritas, axones, sinapsis y prolongaciones de astrocitos y microglía. Ahí ocurre la mayoría de las sinapsis de la sustancia gris."}]}]}]}', NULL, 1);
INSERT OR IGNORE INTO practica_niveles (id, actividad_id, numero, titulo, instrucciones, tipo, activo) VALUES
  (3, 10, 2, 'Cada célula, su función', 'Lee la frase y toca la tarjeta de la célula glial que describe. <strong>Verde</strong>: correcta al primer intento. <strong>Rojo</strong>: esa tarjeta no era; lee la pista y prueba con otra.', 'elegir', 1);
INSERT OR IGNORE INTO practica_items (nivel_id, enunciado, respuesta, sinonimos, pista, explicacion, orden, fila, celda, nota) VALUES
  (3, 'Es la glía más abundante del SNC; sus pies perivasculares rodean los capilares.', 'Astrocito', 'astrocitos|astroglia|astrocito reactivo|astrocitos reactivos',
      'Su nombre viene de su forma de estrella; su marcador clásico es la GFAP.',
      'Sus pies perivasculares inducen y mantienen la barrera hematoencefálica, aunque el sello lo forman las uniones estrechas del endotelio.', 1, NULL, NULL, 'Protoplasmático (sustancia gris, contacta sinapsis) · fibroso (sustancia blanca, contacta nodos de Ranvier).'),
  (3, 'Recapta el glutamato liberado en la sinapsis, lo transforma en glutamina y se la devuelve a la neurona.', 'Astrocito', 'astrocitos|astroglia|astrocito reactivo|astrocitos reactivos',
      'Es la tercera parte de la sinapsis tripartita.',
      'Ciclo glutamato-glutamina. Si falla, el glutamato se acumula y daña a la neurona (excitotoxicidad).', 2, NULL, NULL, NULL),
  (3, 'Con varias prolongaciones forma la mielina de hasta unos 50 axones del SNC.', 'Oligodendrocito', 'oligodendrocitos|oligodendroglia|oligo',
      'Es la célula que mieliniza en el sistema nervioso central.',
      'Cada prolongación forma un internodo en un axón distinto. Su mielina tiene sobre todo PLP.', 3, NULL, NULL, NULL),
  (3, 'Es la célula inmune residente del SNC: vigila el tejido, fagocita restos y poda sinapsis.', 'Microglía', 'microglia|microglias|microgliocito|microgliocitos|celula microglial|celulas microgliales',
      'Su origen no es nervioso: deriva de células del sistema inmune que colonizan el SNC.',
      'Aunque se diga que está «en reposo», sus prolongaciones exploran el tejido todo el tiempo.', 4, NULL, NULL, NULL),
  (3, 'Epitelio cúbico ciliado que tapiza los ventrículos y el canal central de la médula.', 'Célula ependimaria', 'ependimaria|ependimarias|celulas ependimarias|ependimocito|ependimocitos|ependimo|epitelio ependimario',
      'Es la única glía con forma de epitelio.',
      'Sus cilios mueven el LCR y sus uniones forman la barrera entre el LCR y el tejido nervioso.', 5, NULL, NULL, NULL),
  (3, 'Tras una lesión del SNC se vuelve reactivo y forma una cicatriz que protege el tejido sano, pero impide que los axones vuelvan a crecer.', 'Astrocito', 'astrocitos|astroglia|astrocito reactivo|astrocitos reactivos',
      'Es la misma célula que regula la barrera y el glutamato, ahora en estado reactivo.',
      'Gliosis reactiva: la cicatriz glial aísla la lesión, pero es una de las razones por las que el SNC casi no regenera.', 6, NULL, NULL, NULL),
  (3, 'En la esclerosis múltiple, el sistema inmune destruye la mielina que forman los {}.', 'Oligodendrocito', 'oligodendrocitos|oligodendroglia|oligo',
      'La esclerosis múltiple afecta el SNC, no los nervios periféricos.',
      'Sin mielina la conducción se enlentece o se bloquea: fatiga, torpeza motora y alteraciones sensitivas.', 7, NULL, NULL, NULL),
  (3, 'En los plexos coroideos, estas células producen el líquido cefalorraquídeo.', 'Célula ependimaria', 'ependimaria|ependimarias|celulas ependimarias|ependimocito|ependimocitos|ependimo|epitelio ependimario',
      'Son las mismas células que tapizan los ventrículos.',
      'Las ependimarias de los plexos coroideos producen el LCR y regulan su composición iónica.', 8, NULL, NULL, NULL),
  (3, 'Según lo que detecta, pasa de un estado de vigilancia a uno activado: proinflamatorio (M1) o reparador (M2).', 'Microglía', 'microglia|microglias|microgliocito|microgliocitos|celula microglial|celulas microgliales',
      'Es la célula inmune del SNC.',
      'M1 fagocita y secreta citoquinas proinflamatorias; M2 secreta factores neurotróficos y ayuda a resolver la inflamación.', 9, NULL, NULL, NULL),
  (3, 'Durante el desarrollo, la glía radial guía la migración de las neuronas y al madurar se transforma en {}.', 'Astrocito', 'astrocitos|astroglia|astrocito reactivo|astrocitos reactivos',
      'Es la glía más abundante del SNC adulto.',
      'Las prolongaciones de la glía radial son los «rieles» desde la zona ventricular hasta la corteza.', 10, NULL, NULL, NULL);

-- Actividad 11: GLÍA DEL SNP. Nivel I esquema (identificación, labeling_parts; tarea B de Kaira Santos); nivel II práctica «elegir» con cuadro (practica_niveles numero 2); niveles III-IV capturas
INSERT OR IGNORE INTO actividades (id, topic_id, slug, titulo, descripcion, tipo, activo, objetivo, mecanica, fuente) VALUES
  (11, 7, 'glia-snp', 'Glía del SNP',
       'Célula de Schwann y célula satélite, comparadas con la glía del SNC. Nivel I: identifícalas en un esquema. Nivel II: cuadro comparativo SNC frente a SNP. Nivel III: neuronas del ganglio y sus células satélite. Nivel IV: envolturas y fibras de un nervio periférico.',
       'lamina', 1, 'Comparar la glía del SNP con la del SNC y reconocerla en el ganglio y en el nervio periférico.', 'Identificar cada célula en un esquema; leer frases y tocar la tarjeta de la célula para completar el cuadro; capturar, etiquetar y responder en dos láminas.', 'Clase Células del sistema nervioso II 2026 · MH-051 y MH-052 (histologyguide.com)');
INSERT OR IGNORE INTO actividad_recursos (actividad_id, tipo, url, caption, orden) VALUES
  (11, 'tareas', '{"laminas": {"mh051": {"nombre": "Azan (ganglio)", "url": "https://histologyguide.com/slideview/MH-051-dorsal-root-ganglion/06-slide-1.html?x=8730&y=6571&z=6.082", "caption": "Ganglio de la raíz dorsal — Azan (histologyguide.com)"}, "mh052": {"nombre": "H&E (nervio)", "url": "https://histologyguide.com/slideview/MH-052-peripheral-nerve/06-slide-1.html?x=18642&y=16157&z=4.930", "caption": "Nervio periférico — H&E (histologyguide.com)"}}, "niveles": [{"n": 1, "tipo": "identificar", "titulo": "Esquema", "img": "img/glia-snp.jpg"}, {"n": 2, "tipo": "practica", "titulo": "SNC frente a SNP"}, {"n": 3, "tipo": "capturas", "titulo": "Ganglio y células satélite", "laminas": ["mh051"], "instrucciones": "Para cada captura sigue los 4 pasos del panel: buscar y capturar, recortar, etiquetar y responder. <strong>Verde</strong>: correcto. <strong>Rojo</strong>: por repasar. <strong>Naranjo</strong>: lo que estás haciendo.", "capturas": [{"clave": "ganglio", "titulo": "Neurona del ganglio", "lamina": "mh051", "busca": "Busca los somas grandes y redondos agrupados entre haces de fibras; acércate a uno hasta ver qué lo rodea.", "etiquetas": ["Soma neuronal", "Núcleo", "Células satélite", "Haz de fibras"], "preguntas": [{"p": "Cada soma del ganglio está rodeado por un anillo de núcleos pequeños, como la motoneurona de «Glía del SNC». ¿Cuál es la diferencia principal?", "ops": ["Aquí son células satélite y están fuera del SNC, en un ganglio", "Aquí son oligodendrocitos, igual que alrededor de la motoneurona", "Aquí son células de Schwann que forman mielina sobre el soma", "Aquí son fibroblastos de la cápsula que envuelve todo el ganglio"], "ok": 0, "pista": "¿Este corte es del SNC o del SNP? ¿Qué glía corresponde a cada uno?", "exp": "En el ganglio, cada soma está envuelto por células satélite, glía del SNP. Alrededor de la motoneurona (SNC) la glía es oligodendrocitos y astrocitos. En la lámina las dos se ven como un anillo de núcleos: lo que cambia es dónde estás."}, {"p": "Los somas del ganglio se ven redondos y casi sin prolongaciones, a diferencia de la motoneurona. ¿Por qué?", "ops": ["Son pseudounipolares: su única prolongación rara vez queda en el corte", "Son neuronas inmaduras que todavía no forman sus dendritas ni su axón", "Sí tienen muchas ramas, pero el Azan sólo tiñe los somas de neurona", "Son células gliales grandes, no neuronas, y por eso no tienen ramas"], "ok": 0, "pista": "Recuerda cuántas prolongaciones salen del soma de una neurona del ganglio de la raíz dorsal.", "exp": "Del soma de la neurona pseudounipolar sale una sola prolongación, que luego se divide en T. Como es una sola, pocas veces queda dentro del plano del corte, y el soma se ve redondo. La motoneurona, en cambio, es multipolar."}, {"p": "Si las células satélite dejan de retirar el K+ que la neurona libera al disparar, ¿qué esperas?", "ops": ["La neurona queda más excitable y dispara sin estímulo (dolor)", "El axón pierde la mielina y la señal se conduce más lento", "El soma se divide para reemplazar a la neurona que se dañó", "La señal deja de llegar desde el receptor de la piel al soma"], "ok": 0, "pista": "Si el K+ se acumula fuera, la membrana queda más cerca del umbral.", "exp": "Las satélite regulan K+ y glutamato alrededor del soma, como los astrocitos en el SNC. Su alteración vuelve hiperexcitable a la neurona sensitiva: dolor neuropático."}, {"p": "Entre los grupos de somas pasan haces de fibras. Con Azan, cada fibra tiene un centro celeste rodeado por un anillo rosado. ¿Qué es cada parte?", "ops": ["Celeste: el axón; rosado: la mielina que lo envuelve", "Celeste: la mielina; rosado: el axón que va por dentro", "Celeste: el núcleo de Schwann; rosado: su citoplasma", "Celeste: el colágeno; rosado: una dendrita del ganglio"], "ok": 0, "pista": "¿Qué va al centro de una fibra mielinizada y qué la envuelve?", "exp": "Con Azan el axón se ve celeste al centro de cada fibra y la mielina, rosada o roja a su alrededor. El tejido conectivo (endoneuro y cápsula del ganglio) se ve azul oscuro."}]}]}, {"n": 4, "tipo": "capturas", "titulo": "Nervio periférico", "laminas": ["mh052"], "instrucciones": "Para cada captura sigue los 4 pasos del panel: buscar y capturar, recortar, etiquetar y responder. <strong>Verde</strong>: correcto. <strong>Rojo</strong>: por repasar. <strong>Naranjo</strong>: lo que estás haciendo.", "capturas": [{"clave": "nervio", "objeto": "la zona", "titulo": "Nervio en corte transversal", "lamina": "mh052", "busca": "Mira las envolturas del nervio entero, de cada grupo de fibras (fascículo) y de cada fibra. Acércate a un fascículo hasta ver círculos claros con un punto al centro.", "etiquetas": ["Epineuro", "Perineuro", "Fascículo", "Endoneuro", "Fibra mielinizada"], "preguntas": [{"p": "Cada fibra mielinizada se ve como un círculo claro con un punto al centro. ¿Qué es el espacio claro?", "ops": ["La mielina, cuyos lípidos se disuelven al procesar el tejido", "El axón, que se hinchó y quedó vacío al fijar el tejido", "El endoneuro, el tejido conectivo que rodea a todo el fascículo", "Un capilar sanguíneo que acompaña a cada fibra nerviosa"], "ok": 0, "pista": "El punto central es el axón. ¿Qué lo envuelve?", "exp": "La mielina es rica en lípidos, que el procesamiento para H&E disuelve: queda un halo claro alrededor del axón."}, {"p": "En el corte transversal ves dos tipos de núcleos: unos grandes y redondos pegados a un axón, y otros pequeños entre las fibras. ¿De qué células son?", "ops": ["Los grandes, de células de Schwann; los pequeños, de fibroblastos", "Los grandes, de fibroblastos; los pequeños, de células de Schwann", "Los grandes, de neuronas; los pequeños, de células de Schwann", "Los grandes, de oligodendrocitos; los pequeños, de fibroblastos"], "ok": 0, "pista": "En un nervio no hay somas de neuronas. ¿Qué célula va pegada a cada axón?", "exp": "El núcleo de la célula de Schwann queda al lado del axón que envuelve. Los núcleos pequeños, los más numerosos, son de fibroblastos del endoneuro. En un nervio no hay somas neuronales, sólo sus prolongaciones; y los oligodendrocitos están en el SNC."}, {"p": "¿Qué envoltura separa cada fascículo y actúa como barrera entre la sangre y las fibras?", "ops": ["El perineuro, con capas de células unidas entre sí", "El epineuro, que recubre todo el nervio por fuera", "El endoneuro, que rodea a cada fibra por separado", "La mielina, que aísla a cada axón de los demás"], "ok": 0, "pista": "Busca la envoltura que rodea a cada grupo de fibras.", "exp": "Epineuro: todo el nervio. Perineuro: cada fascículo; sus células unidas forman la barrera hemato-nerviosa. Endoneuro: cada fibra."}]}]}]}', NULL, 1);
INSERT OR IGNORE INTO practica_niveles (id, actividad_id, numero, titulo, instrucciones, tipo, activo) VALUES
  (4, 11, 2, 'SNC frente a SNP', 'Lee la frase y toca la tarjeta de la célula que describe. Cada acierto escribe una celda del cuadro, fila por fila: dónde está, qué envuelve y qué pasa si falla. <strong>Rojo</strong>: esa tarjeta no era; prueba con otra.', 'elegir', 1);
INSERT OR IGNORE INTO practica_items (nivel_id, enunciado, respuesta, sinonimos, pista, explicacion, orden, fila, celda, nota) VALUES
  (4, 'Está en el SNP, a lo largo de los axones de los nervios periféricos.', 'Célula de Schwann', 'schwann|celulas de schwann|celula schwann|lemocito|neurolemocito',
      'Mieliniza fuera del encéfalo y la médula.',
      'Acompaña a los axones desde la raíz hasta el músculo o el receptor.', 1, 'dónde está', 'SNP · nervios periféricos', NULL),
  (4, 'Está en el SNC, sobre todo en la sustancia blanca, alineada entre los axones.', 'Oligodendrocito', 'oligodendrocitos|oligodendroglia|oligo',
      'Es la glía que forma mielina dentro del SNC.',
      'Sus núcleos forman hileras entre las fibras de la sustancia blanca.', 2, 'dónde está', 'SNC · sustancia blanca', NULL),
  (4, 'Está en el SNP, dentro de los ganglios sensitivos y autonómicos.', 'Célula satélite', 'satelite|satelites|celulas satelite|celulas satelites|celula satelite',
      'Piensa en el ganglio de la raíz dorsal.',
      'Rodea los somas de las neuronas de los ganglios.', 3, 'dónde está', 'SNP · ganglios', NULL),
  (4, 'Está en el SNC, en la sustancia gris y en la blanca, con pies sobre los capilares.', 'Astrocito', 'astrocitos|astroglia|astrocito reactivo|astrocitos reactivos',
      'Es la glía más abundante del SNC.',
      'Protoplasmático en la sustancia gris y fibroso en la blanca.', 4, 'dónde está', 'SNC · sustancia gris y blanca', NULL),
  (4, 'Cada célula forma la mielina de un solo internodo de un solo axón.', 'Célula de Schwann', 'schwann|celulas de schwann|celula schwann|lemocito|neurolemocito',
      'Una célula, un internodo.',
      'Un axón periférico largo necesita cientos de estas células en fila.', 5, 'qué envuelve', '1 internodo de 1 axón', NULL),
  (4, 'Con varias prolongaciones mieliniza internodos de muchos axones a la vez.', 'Oligodendrocito', 'oligodendrocitos|oligodendroglia|oligo',
      'Una célula, muchos axones.',
      'Hasta unos 50 axones: si muere una sola, se desmielinizan muchos.', 6, 'qué envuelve', 'Internodos de hasta ~50 axones', NULL),
  (4, 'Forma una cápsula alrededor del soma de cada neurona.', 'Célula satélite', 'satelite|satelites|celulas satelite|celulas satelites|celula satelite',
      'No envuelve axones, sino somas.',
      'La cápsula regula el microambiente del soma en el ganglio.', 7, 'qué envuelve', 'Cápsula alrededor del soma', NULL),
  (4, 'Envuelve sinapsis, nodos de Ranvier y capilares, pero no forma mielina.', 'Astrocito', 'astrocitos|astroglia|astrocito reactivo|astrocitos reactivos',
      'Conecta neurona, sinapsis y vaso sanguíneo.',
      'Participa de la sinapsis tripartita y de la unidad neurovascular.', 8, 'qué envuelve', 'Sinapsis, nodos y capilares (sin mielina)', NULL),
  (4, 'Su daño en el síndrome de Guillain-Barré enlentece o bloquea la conducción en los nervios.', 'Célula de Schwann', 'schwann|celulas de schwann|celula schwann|lemocito|neurolemocito',
      'Guillain-Barré afecta los nervios periféricos.',
      'Su neurilema y su lámina basal guían al axón que vuelve a crecer: por eso muchos pacientes se recuperan.', 9, 'si falla', 'Guillain-Barré · permite regenerar', NULL),
  (4, 'Su daño en la esclerosis múltiple deja placas sin mielina en el encéfalo y la médula.', 'Oligodendrocito', 'oligodendrocitos|oligodendroglia|oligo',
      'La esclerosis múltiple afecta el SNC.',
      'Sin neurilema y con cicatriz glial, el SNC casi no regenera.', 10, 'si falla', 'Esclerosis múltiple · casi no regenera', NULL),
  (4, 'Cuando se altera, la neurona del ganglio queda hiperexcitable y aparece dolor neuropático.', 'Célula satélite', 'satelite|satelites|celulas satelite|celulas satelites|celula satelite',
      'Es la glía que rodea los somas sensitivos.',
      'Regula K+ y glutamato alrededor del soma, igual que el astrocito en el SNC.', 11, 'si falla', 'Dolor neuropático', NULL),
  (4, 'Si deja de recaptar glutamato, las neuronas vecinas mueren por excitotoxicidad.', 'Astrocito', 'astrocitos|astroglia|astrocito reactivo|astrocitos reactivos',
      'Es la célula del ciclo glutamato-glutamina.',
      'También participa en el edema y forma la cicatriz glial tras una lesión.', 12, 'si falla', 'Excitotoxicidad, edema, cicatriz glial', NULL);

-- Esquemas de glía (tarea B, Kaira Santos): img/glia-snc.jpg y img/glia-snp.jpg, 1536×1024; prompts en docs/prompts-imagenes.md §4.
-- Ajustar coordenadas con actividad.php?slug=<slug>&nivel=1&calibrar=1
INSERT OR IGNORE INTO labeling_parts (actividad_id, nombre, x_pct, y_pct, descripcion, funcion, sinonimos, box_x_pct, box_y_pct, orden, forma) VALUES
  (10, 'Astrocito', 28.8, 24.5,
      'Es la glía más grande, con forma de estrella. Sus pies perivasculares abrazan los capilares y ayudan a mantener la barrera hematoencefálica. Ante una lesión forma la cicatriz glial.',
      'Mantiene el ambiente químico de las neuronas: retira neurotransmisores y potasio y les aporta energía.',
      'astroglia|+astroglía|celula astrocitaria|astrocito protoplasmico|astrocito protoplasmatico|astrocito fibroso', 8, 33, 1, 'elipse:28.8,24.8,4.6,7.2'),
  (10, 'Oligodendrocito', 66.2, 28.5,
      'Uno solo mieliniza segmentos de muchos axones distintos. En la sustancia blanca sus núcleos se ordenan en hileras entre las fibras; otros se ubican junto a somas grandes.',
      'Forma la vaina de mielina en el SNC: cada una de sus prolongaciones envuelve un segmento de axón.',
      'oligodendroglia|+oligodendroglía|oligodendrocito interfascicular|oligodendrocito satelite', 66, 13, 2, 'elipse:66.2,28.3,3.3,5.2'),
  (10, 'Microglía', 15.0, 62.0,
      'Es la glía más pequeña: núcleo alargado y ramas finas que exploran el tejido. Al activarse se vuelve redonda (ameboide). No nace del tubo neural como el resto: viene del linaje de los macrófagos.',
      'Vigila el tejido y fagocita restos celulares y microorganismos: es la defensa inmune del SNC.',
      'microglia|celula microglial|+célula microglial|celula de microglia|celula de hortega|+célula de Hortega|microgliocito', 5, 49, 3, 'elipse:15.0,62.3,3.8,2.7'),
  (10, 'Célula ependimaria', 50.0, 79.7,
      'Forma un epitelio cúbico simple que tapiza los ventrículos y el canal central de la médula. En los plexos coroideos, un epéndimo modificado produce el líquido cefalorraquídeo.',
      'Reviste las cavidades del SNC y, con sus cilios, hace circular el líquido cefalorraquídeo.',
      'ependimaria|ependimocito|+ependimocito|ependimo|epéndimo|celula del ependimo|epitelio ependimario|celula ependimal', 76, 72, 4, 'puntos:39.0,81.2;61.1,81.1');
INSERT OR IGNORE INTO labeling_parts (actividad_id, nombre, x_pct, y_pct, descripcion, funcion, sinonimos, box_x_pct, box_y_pct, orden, forma) VALUES
  (11, 'Célula satélite', 16.5, 15.1,
      'Forma una capa continua de células aplanadas alrededor de cada soma del ganglio. Con H&E se ve como un anillo de núcleos pequeños alrededor de la neurona.',
      'Envuelve el soma de las neuronas de los ganglios y regula el medio químico que lo rodea.',
      'satelite|satelites|glia satelite|+glía satélite|celula capsular|+célula capsular|anficito', 6, 9, 1, 'puntos:10.0,24.6;14.5,35.8'),
  (11, 'Célula de Schwann mielinizante', 38.4, 28.5,
      'Un axón largo necesita muchas, una tras otra. Su núcleo queda por fuera de la mielina. Tras una lesión guía el rebrote del axón: por eso un nervio periférico puede regenerarse.',
      'Se enrolla en un solo axón del SNP y forma la mielina de un único segmento.',
      'celula de schwann|schwann|schwann mielinizante|+célula de Schwann|lemocito|neurolemocito', 40, 17, 2, 'elipse:39.4,31.8,7.4,5.0'),
  (11, 'Célula de Schwann no mielinizante', 81.5, 68.4,
      'Así viajan las fibras delgadas y lentas, como las del dolor y la temperatura. Una célula con sus axones forma un haz de Remak.',
      'Envuelve varios axones delgados a la vez, cada uno en un surco de su membrana, sin formar mielina.',
      'schwann no mielinizante|celula de remak|+célula de Remak|schwann de remak|schwann amielinica|celula de schwann amielinica', 92, 62, 3, 'elipse:76.0,69.8,6.2,12.2'),
  (11, 'Oligodendrocito', 77.5, 11.7,
      'Compáralo con la célula de Schwann: uno mieliniza segmentos de muchos axones (SNC); la otra, un solo segmento de un axón (SNP).',
      'Forma la vaina de mielina en el SNC: cada una de sus prolongaciones envuelve un segmento de axón.',
      'oligodendroglia|+oligodendroglía', 66, 8, 4, 'elipse:77.4,12.0,3.2,5.0');

-- Actividad 12: QUIZ de cierre Células nerviosas II (circuitos y glía)
INSERT OR IGNORE INTO actividades (id, topic_id, slug, titulo, descripcion, tipo, activo) VALUES
  (12, 7, 'quiz-celulas-nerviosas-2', 'Quiz: Células nerviosas II (circuitos y glía)',
       'Cierre del práctico: preguntas de un pool común y casos de tu carrera (TO o Fono); algunas se responden con tarjetas. Una sola oportunidad por pregunta; cada respuesta muestra una explicación.', 'quiz', 1);
INSERT OR IGNORE INTO quices (actividad_id, titulo, datos_json, activo) VALUES
  (12, 'Células nerviosas II', '[{"id": "c01", "carrera": "comun", "pregunta": "¿Cuál es el orden de los componentes de un arco reflejo?", "opciones": ["Receptor → neurona sensitiva → interneurona → motoneurona → efector", "Receptor → motoneurona → interneurona → neurona sensitiva → efector", "Efector → neurona sensitiva → interneurona → motoneurona → receptor", "Receptor → interneurona → neurona sensitiva → motoneurona → efector"], "correcta": 0, "feedback": "La información entra por la vía sensitiva, se integra en la médula y sale por la vía motora hacia el efector (músculo o glándula)."}, {"id": "c02", "carrera": "comun", "pregunta": "¿Qué lleva la raíz dorsal y qué lleva la raíz ventral de un nervio espinal?", "opciones": ["Dorsal: información sensitiva que entra; ventral: órdenes motoras que salen", "Dorsal: órdenes motoras que salen; ventral: información sensitiva que entra", "Dorsal y ventral: ambas llevan información sensitiva y órdenes motoras", "Dorsal y ventral: ambas llevan solo órdenes motoras hacia los músculos"], "correcta": 0, "feedback": "Raíz dorsal = entrada sensitiva (con su ganglio); raíz ventral = salida motora. Después se unen y el nervio espinal es mixto."}, {"id": "c03", "carrera": "comun", "pregunta": "Un nervio periférico mixto contiene axones de neuronas cuyos somas están en:", "opciones": ["El ganglio de la raíz dorsal (sensitivas) y el asta ventral (motoras)", "El asta dorsal (sensitivas) y el ganglio de la raíz ventral (motoras)", "El propio nervio, repartidos entre los fascículos de sus fibras", "La corteza cerebral, desde donde los axones bajan sin interrupción"], "correcta": 0, "feedback": "El nervio solo tiene axones y glía (Schwann). Los somas están en el ganglio (sensitivas) o en el asta ventral de la médula (motoneuronas)."}, {"id": "c04", "carrera": "comun", "pregunta": "Durante el desarrollo se forman más sinapsis de las necesarias. ¿Qué célula elimina las que no se usan (poda sináptica)?", "opciones": ["Astrocito", "Oligodendrocito", "Microglía", "Célula ependimaria"], "correcta": 2, "feedback": "La microglía poda las sinapsis poco activas; así se refinan los circuitos. Una poda excesiva se asocia a enfermedades del neurodesarrollo y neurodegenerativas.", "tarjetas": true}, {"id": "c05", "carrera": "comun", "pregunta": "Un axón del nervio ciático está mielinizado por muchas células, una detrás de otra. ¿Cuáles son?", "opciones": ["Oligodendrocito", "Célula de Schwann", "Célula satélite", "Astrocito"], "correcta": 1, "feedback": "En el SNP cada célula de Schwann forma un solo internodo: un axón largo necesita cientos de ellas en fila.", "tarjetas": true}, {"id": "c06", "carrera": "comun", "pregunta": "Además de aumentar la velocidad, ¿por qué la mielina permite que la neurona ahorre energía?", "opciones": ["El potencial se regenera solo en los nodos: se bombean menos iones", "La mielina produce ATP y se lo entrega directamente al axón", "El axón mielinizado no necesita canales de Na+ en ningún punto", "La mielina guarda glucosa y la libera cuando el axón la necesita"], "correcta": 0, "feedback": "En el internodo casi no hay intercambio de iones; los canales de Na+ se concentran en los nodos. Menos iones que entran = menos trabajo de la bomba Na+/K+ = menos ATP."}, {"id": "c07", "carrera": "comun", "pregunta": "¿Qué forma la «unidad neurovascular»?", "opciones": ["Endotelio, astrocitos y neuronas: regulan qué entra y cuánta sangre llega", "Oligodendrocitos y axones, que deciden qué tan rápido viaja la señal", "Ependimarias y LCR, que deciden cuánto líquido llena los ventrículos", "Microglía y neuronas, que deciden qué sinapsis se eliminan y cuáles no"], "correcta": 0, "feedback": "El capilar con su endotelio, las estructuras que lo rodean (pies de astrocitos) y la neurona trabajan juntos: regulan la barrera y el flujo sanguíneo local según la actividad."}, {"id": "k1", "carrera": "comun", "pregunta": "Una persona con diabetes pierde el reflejo aquíleo y la sensibilidad en los pies; el estudio muestra conducción lenta en los nervios de las piernas. ¿Qué glía está dañada?", "opciones": ["Oligodendrocito", "Célula de Schwann", "Célula satélite", "Astrocito"], "correcta": 1, "feedback": "La conducción lenta en nervios periféricos indica daño de la mielina del SNP, que forman las células de Schwann.", "tarjetas": true}, {"id": "k2", "carrera": "comun", "pregunta": "En un brote de esclerosis múltiple, la resonancia muestra placas en la sustancia blanca del encéfalo. ¿Qué célula es el blanco del daño?", "opciones": ["Astrocito", "Oligodendrocito", "Microglía", "Célula ependimaria"], "correcta": 1, "feedback": "La esclerosis múltiple destruye la mielina del SNC, que forman los oligodendrocitos.", "tarjetas": true}, {"id": "k3", "carrera": "comun", "pregunta": "Tras un traumatismo encefálico se altera la circulación del LCR y aparece hidrocefalia. ¿Qué glía produce y mueve el LCR?", "opciones": ["Astrocito", "Oligodendrocito", "Microglía", "Célula ependimaria"], "correcta": 3, "feedback": "Las ependimarias producen el LCR en los plexos coroideos y lo mueven con sus cilios.", "tarjetas": true}, {"id": "k4", "carrera": "comun", "pregunta": "Después de un herpes zóster, una persona queda con dolor quemante sin lesión visible en la piel. ¿Qué glía del ganglio sensitivo se asocia a ese dolor neuropático?", "opciones": ["Oligodendrocito", "Célula de Schwann", "Célula satélite", "Astrocito"], "correcta": 2, "feedback": "El virus queda latente en el ganglio sensitivo. Las células satélite alteradas dejan a la neurona hiperexcitable: dolor neuropático.", "tarjetas": true}, {"id": "t1", "carrera": "terapia-ocupacional", "pregunta": "Al golpear el tendón rotuliano la pierna no se extiende, pero la persona siente el golpe. ¿Dónde está la falla más probable del circuito?", "opciones": ["En la motoneurona del asta ventral o en su axón por la raíz ventral", "En la neurona sensitiva del ganglio o en su rama por la raíz dorsal", "En la corteza motora, que no alcanza a enviar la orden voluntaria", "En el cerebelo, que no alcanza a coordinar la contracción del músculo"], "correcta": 0, "feedback": "Si siente el golpe, la vía sensitiva funciona. La falla está en la salida motora. El reflejo no necesita la corteza ni el cerebelo."}, {"id": "t2", "carrera": "terapia-ocupacional", "pregunta": "En la rehabilitación tras un ACV, la práctica repetida favorece la formación de sinapsis nuevas y la eliminación de las que no se usan. ¿Qué glía participa?", "opciones": ["Astrocitos (forman sinapsis) y microglía (poda las que no se usan)", "Oligodendrocitos (forman sinapsis) y ependimarias (podan las que sobran)", "Células de Schwann (forman sinapsis) y satélite (podan las que sobran)", "Microglía (forma sinapsis) y astrocitos (podan las que no se usan)"], "correcta": 0, "feedback": "Los astrocitos favorecen la sinaptogénesis y la plasticidad; la microglía poda sinapsis. Ambas son parte de la base celular de la rehabilitación."}, {"id": "t3", "carrera": "terapia-ocupacional", "pregunta": "En la ELA, astrocitos que recaptan poco glutamato contribuyen a la muerte de las motoneuronas. ¿Cuál es el mecanismo?", "opciones": ["El glutamato se acumula en la sinapsis y sobreexcita a la neurona", "Falta glutamato en la sinapsis y la neurona deja de recibir señales", "Los astrocitos fagocitan a las motoneuronas que tienen poco glutamato", "El glutamato destruye la mielina que rodea al axón de la motoneurona"], "correcta": 0, "feedback": "Excitotoxicidad: el exceso de glutamato abre demasiados canales, entra Ca2+ en exceso y la neurona muere."}, {"id": "t4", "carrera": "terapia-ocupacional", "pregunta": "Retiras la mano de una olla caliente antes de sentir dolor. ¿Qué permite que la orden salga tan rápido?", "opciones": ["Interneuronas de la médula conectan la vía sensitiva con la motora", "La corteza motora recibe el estímulo antes que el resto del encéfalo", "Las neuronas sensitivas llegan directo al músculo sin pasar por la médula", "El cerebelo envía la orden de retirada antes que la corteza"], "correcta": 0, "feedback": "Es un reflejo de retirada (polisináptico): el circuito se cierra en la médula. La sensación de dolor llega después, cuando la señal sube a la corteza."}, {"id": "f1", "carrera": "fonoaudiologia", "pregunta": "El reflejo nauseoso se gatilla al tocar la pared posterior de la faringe. Como todo reflejo tiene vía sensitiva, centro y vía motora. ¿Dónde se cierra su circuito?", "opciones": ["En el tronco encefálico, en núcleos de los nervios craneales", "En el asta ventral de la médula espinal, a nivel cervical", "En la corteza motora orofacial del lóbulo frontal izquierdo", "En el ganglio sensitivo del nervio que inerva la faringe"], "correcta": 0, "feedback": "Los reflejos de la cabeza y el cuello (nauseoso, deglutorio, corneal) se integran en el tronco encefálico, con vías por los nervios craneales (IX y X en el nauseoso)."}, {"id": "f2", "carrera": "fonoaudiologia", "pregunta": "En la esclerosis múltiple puede aparecer habla lenta y entrecortada (disartria) por placas en el tronco y el cerebelo. ¿Por qué se altera la señal?", "opciones": ["Se pierde la mielina de los oligodendrocitos y la señal se enlentece", "Se pierde la mielina de las células de Schwann: el impulso se acelera", "Mueren las motoneuronas de la lengua: el músculo se atrofia", "Se bloquean las sinapsis por exceso de LCR en los ventrículos"], "correcta": 0, "feedback": "Las placas desmielinizan axones del SNC: la conducción se enlentece o se bloquea y se pierde la coordinación fina de la articulación."}, {"id": "f3", "carrera": "fonoaudiologia", "pregunta": "Un schwannoma vestibular (neurinoma del acústico) produce hipoacusia de un lado y tinnitus. ¿De qué células nace este tumor?", "opciones": ["Oligodendrocito", "Célula de Schwann", "Célula satélite", "Astrocito"], "correcta": 1, "feedback": "Nace de las células de Schwann del nervio vestibular; al crecer comprime el nervio coclear vecino.", "tarjetas": true}, {"id": "f4", "carrera": "fonoaudiologia", "pregunta": "Cerca del tronco encefálico, la mielina del nervio auditivo deja de formarla la célula de Schwann y pasa a formarla el oligodendrocito. ¿Qué indica ese cambio?", "opciones": ["Que el nervio pasa del SNP al SNC", "Que el nervio pasa de sensitivo a motor", "Que el axón termina y empieza otro", "Que el nervio pierde toda su mielina"], "correcta": 0, "feedback": "La zona de transición marca el límite SNP–SNC. Los schwannomas vestibulares suelen nacer cerca de esa zona."}]', 1);
INSERT OR IGNORE INTO actividad_carrera (actividad_id, carrera_id, descripcion, orden) VALUES
  (12, 2, 'Responde solo/a, sin apuntes. Al terminar revisa el resumen: las preguntas falladas son las que conviene repasar.', 1);
